import type { CourseLesson, CourseQuestion } from './course-types';

export const SCIENCE_CURRICULUM_SOURCE = 'https://www.gov.uk/government/publications/national-curriculum-in-england-science-programmes-of-study/national-curriculum-in-england-science-programmes-of-study';
export const SCIENCE_ALLOCATION_NOTE = 'This original 36-week sequence follows England’s primary science topics and allocates KS3 content editorially across Years 7–9. Schools can sequence content within a key stage. A teacher should review progression, accessibility and local examples. Paper models and safe observations support learning; they do not replace supervised practical science, school laboratory work or assessed curriculum coverage.';
const SPACE_SOURCE = 'https://science.nasa.gov/solar-system/';
const ATOM_SOURCE = 'https://edu.rsc.org/cpd/use-post-16-atomic-models-to-inform-14-16-understanding/4016023.article';

type Concept = {title:string;word:string;meaning:string;explanation:string;prompt:string;right:string;wrong:[string,string];task:string};
type Unit = {year:number;name:string;introduction:string;enquiry:[string,string,string,string,string];source:string;concepts:Concept[]};
const UNITS:Unit[]=[];
// Each row is an authored weekly concept: title, vocabulary, explanation,
// question/answer/distractors and a topic-specific paper or observation task.
// Neighbouring concepts are revisited as retrieval, not counted as extra lessons.
function unit(year:number,name:string,introduction:string,enquiry:Unit['enquiry'],rows:string,source=SCIENCE_CURRICULUM_SOURCE){
  const concepts=rows.trim().split('\n').map(row=>{
    const fields=row.trim().split('~');
    if(fields.length!==9)throw new Error(`Invalid science concept: ${row}`);
    const [title,word,meaning,explanation,prompt,right,wrong1,wrong2,task]=fields;
    return {title,word,meaning,explanation,prompt,right,wrong:[wrong1,wrong2] as [string,string],task};
  });
  if(concepts.length!==6)throw new Error(`Science unit ${name} needs six weekly concepts`);
  UNITS.push({year,name,introduction,enquiry,source,concepts});
}

unit(1,'Plants around us','Plants grow in many places. Dandelions and common daisies are common wild flowers. Roses and sunflowers are often grown in gardens. A plant can grow in a garden and in the wild. Look at named pictures with a grown-up. Do not pick or taste unknown plants. Different parts have different jobs.',
  ['How can we compare two leaves?','Look at both and describe their shapes','Guess without looking','Pull up both plants','Look at the same feature on each leaf. A drawing helps us show a difference.'],`
Roots below the ground~root~a plant part that takes in water~Roots usually grow in the ground. They help hold a plant in place and take in water. A dandelion has a main root called a taproot. A root is not the same part as a leaf.~Which part usually takes in water from the ground?~Roots~Flowers~Petals~Use a named dandelion picture. Draw its yellow flower head and label its root below the ground.
Stems that hold plants up~stem~the part that supports leaves and flowers~A stem holds parts of a plant above the ground. A tree has a thick woody stem called a trunk. Some plants have soft green stems.~What is a tree’s main woody stem called?~A trunk~A petal~A seed~Draw a tree trunk and a soft flower stem side by side.
Leaves with different shapes~leaf~a plant part that uses light to help make food~Leaves can be wide, narrow or divided into smaller parts. Many are green. We can describe a leaf’s shape without knowing the plant’s name.~Which feature helps compare two leaves?~Their shapes~The name of your school~The colour of your pencil~Draw two different leaf shapes from a picture or safe observation.
Flowers and petals~petal~a part around the middle of many flowers~Many plants have flowers. A common daisy usually has white outer petals around a yellow middle. A dandelion has a yellow flower head. Garden roses can have pink, red or other colours. A flower is one part of a plant, not the whole plant. Colour alone cannot name every plant.~Which part belongs to many flowers?~Petals~Wheels~Fur~Compare named pictures of a common daisy, dandelion, rose and sunflower. Draw two and label their names and one difference.
Deciduous trees~deciduous~a tree that loses its leaves at a season of the year~Many trees in England lose their leaves in autumn and grow new ones in spring. We call these trees deciduous. Common oak is one example. A bare tree in winter is not necessarily dead.~What can a living deciduous tree do in winter?~Have no leaves~Turn into a rock~Never grow again~Draw a common oak in summer and winter. Label its name and show the change in leaves.
Evergreen trees~evergreen~a plant that keeps leaves through the year~Evergreen trees keep leaves through the year, though they can shed old leaves. Common holly is one example. Its leaves are often shiny and spiny. Some other evergreen trees have needles. Not every tree with green summer leaves is evergreen.~What makes a tree evergreen?~It keeps leaves through the year~It never loses any old leaf~It only has leaves in summer~Use named pictures of common oak and common holly. Make two groups: evergreen and deciduous. Do not touch spiny leaves or pick berries.
`);
unit(1,'Animal groups','Animals have different body parts. A picture can help us compare them. We group animals using features, rather than just their size or where we first saw them.',
 ['Which comparison helps group a bird and a cat?','Look for feathers or fur','Choose the bigger animal','Choose your favourite colour','Feathers and fur are body features. Size alone does not tell us an animal’s group.'],`
Fish in water~fish~an animal with gills and usually fins~Fish use gills to get oxygen from water. Most have fins that help them move. A whale lives in water but is a mammal, not a fish.~Which part does a fish use to get oxygen from water?~Gills~Feathers~Petals~Draw a fish with a fin and gills; label both.
Amphibians and frogs~amphibian~an animal group that includes frogs and newts~Many amphibians begin life in water and later spend time on land. A frog is an amphibian. A frog and a fish do not belong to the same group.~Which animal is an amphibian?~A frog~A sparrow~A cat~Draw a frog beside a pond, without touching real animals.
Reptiles and scales~reptile~an animal group that includes snakes and lizards~Reptiles such as snakes and lizards have scaly skin. They breathe air. A snake is not a worm, even though both can have long bodies.~Which animal is a reptile?~A snake~An earthworm~A robin~Compare a snake picture with a worm picture; draw one difference.
Birds have feathers~feather~a covering found on birds~Birds have feathers. Many birds fly, but some cannot. A penguin is still a bird because it has bird features, including feathers.~What do all birds have?~Feathers~Fur~Six legs~Draw a flying bird and a penguin; label feathers on both.
Mammals and fur~mammal~an animal group whose mothers make milk for young~Cats, dogs and humans are mammals. Mammal mothers make milk for their young. Many mammals have fur or hair; living in water does not make a dolphin a fish.~Which animal is a mammal?~A dolphin~A goldfish~A butterfly~Make a picture group containing a cat, human and dolphin.
Different animal diets~omnivore~an animal that eats plants and animals~Herbivores eat plants. Carnivores eat other animals. Omnivores eat both plants and animals. We group a diet by what is eaten, not by how fierce an animal looks.~What does an omnivore eat?~Plants and animals~Only plants~Only animals~Draw three food groups and add a made-up example menu to each.
`);
unit(1,'Our bodies and senses','People use different senses to find out about the world. Some people use aids or other ways to notice things. Use pictures and familiar safe objects; never taste an unknown thing.',
 ['What is a safe way to compare textures?','Feel a safe familiar object with permission','Taste an unknown object','Touch a hot pan','Touch can tell us about texture. A grown-up can choose something safe.'],`
Naming body parts~elbow~the joint in the middle of an arm~An arm has an elbow. A leg has a knee. Joints help parts of our bodies bend; the names help us describe where something is.~Which joint is part of an arm?~Elbow~Knee~Ankle~Draw a simple person and label an elbow and a knee.
Seeing with eyes~sight~the sense that helps us see~Eyes help us see colour and shape when there is enough light. People may use glasses or other aids. Never look directly at the Sun.~Which body part helps with sight?~Eyes~Ears~Knees~Describe the colour and shape of a familiar object in a drawing.
Hearing with ears~hearing~the sense that helps us notice sounds~Ears help us hear sounds. A quiet sound and a loud sound can come from the same thing. We protect our ears from very loud sounds.~Which body part helps us hear?~Ears~Toes~Teeth~Draw two everyday sound sources and label one usually quiet.
Smelling with the nose~smell~the sense that helps us notice scents~The nose helps us notice smells. A smell does not always tell us whether something is safe. Do not sniff unknown chemicals or put things in your nose.~Which body part helps us smell?~Nose~Elbow~Foot~Draw a familiar flower and label the sense used to notice its scent.
Tasting familiar food~taste~the sense that helps us notice flavours~The tongue helps us taste food. Foods can have different flavours. We only eat food a grown-up says is safe for us, including checking allergies.~Which body part helps us taste?~Tongue~Hair~Finger~Draw two familiar foods and describe their tastes without eating anything.
Touch and texture~texture~how a surface feels~Touch helps us notice whether a safe surface feels rough or smooth. The skin has sensors. We can compare textures without pressing hard or touching anything sharp.~Which pair describes texture?~Rough and smooth~Monday and Tuesday~Near and far~Draw a rough-looking and a smooth-looking safe object.
`);
unit(1,'Everyday materials','An object is a thing, such as a cup. A material is what it is made from. One object can contain more than one material, and one material can be used for many objects.',
 ['How can we sort cups by material?','Group cups made from the same material','Group only by who owns them','Break each cup to find out','A material group could include metal cups. Do not break objects to study them.'],`
Objects and materials~material~what an object is made from~A wooden chair is an object made from wood. A metal spoon is made from metal. The object’s name and the material’s name answer different questions.~What is the material in a wooden chair?~Wood~Chair~Kitchen~Draw an object and write its material beside it.
Wood and its uses~wood~a material that comes from trees~Wood is used for many objects, including some furniture. It is usually stiff in thick pieces. A thin piece and a thick piece need not bend in the same way.~Which object can be made from wood?~A table~A cloud~A puddle~Draw two household objects that can be made from wood.
Metal objects~metal~a group of materials often used for strong objects~Many spoons and pans are made from metal. Different metals have different properties. Shiny does not always mean metal: some plastic can look shiny too.~Which object is often made from metal?~A saucepan~A leaf~A raindrop~Find a safe metal object in a picture and draw its use.
Plastic in many forms~plastic~a manufactured material used for many objects~Plastic can be stiff or bendy. A plastic ruler and a plastic bag do not behave in exactly the same way. We describe the actual object carefully.~Can different plastic objects be stiff or bendy?~Yes~No; all are stiff~No; all are bendy~Draw a stiff plastic object and a bendy plastic object.
Glass and seeing through~transparent~letting light pass so we can see through~Clear glass can be transparent. Some glass is coloured or not clear. Glass can break, so look at a window without handling loose glass.~What does transparent mean?~You can see through it~It soaks up every liquid~It is always soft~Draw a view through a window and label the glass.
Water and rock~liquid~a material that flows and takes the shape of its container~Water at normal room temperature is a liquid. A rock is a solid. A solid object and a liquid do not hold their shapes in the same way.~Which is a liquid at normal room temperature?~Water~A rock~A wooden block~Draw water in two differently shaped cups and a solid rock.
`);
unit(1,'Seasons and weather','England has four seasons. Weather can change from day to day within a season. Compare records over time rather than deciding a whole season from one afternoon.',
 ['How can we find out about weather over a week?','Record it each day','Look once and guess every day','Choose the nicest weather','A daily record lets us compare days. One day cannot show a whole week.'],`
Spring changes~spring~the season between winter and summer~In spring, many plants grow new leaves and flowers. Days generally become longer in England. Weather still varies, and not every spring day is warm.~Which season comes after winter?~Spring~Autumn~Winter again~Draw two plant changes that can happen in spring.
Summer daylight~summer~the season between spring and autumn~Summer usually has longer daylight than winter in England. Some days are rainy. We use shade and grown-up guidance outdoors, and never look at the Sun.~How does summer daylight usually compare with winter in England?~It lasts longer~It lasts less time~There is no daylight~Draw a summer-day plan with a place for shade.
Autumn leaves~autumn~the season between summer and winter~Many deciduous trees lose leaves in autumn. Their leaves may change colour first. Evergreen trees still have leaves, so trees do not all change in the same way.~What do many deciduous trees do in autumn?~Lose their leaves~Grow feathers~Become animals~Draw a leafy branch and an autumn branch.
Winter daylight~winter~the season between autumn and spring~Winter days have less daylight than summer days in England. Snow can happen, but it does not snow every day or everywhere. Weather records help us check.~Does every winter day in England have snow?~No~Yes~Only if it is Monday~Draw symbols for two different kinds of winter weather.
Describing today’s weather~weather~what the air and sky are like at a place and time~Weather can be sunny, cloudy, rainy or windy. More than one description can fit a day. A cloudy sky can still have wind.~Can a day be both cloudy and windy?~Yes~No; clouds stop all wind~No; only one word is allowed~Draw a weather symbol chart for an imaginary three-day week.
Daylight is not temperature~daylight~the time when natural light from the Sun is available~Sunrise and sunset help describe daylight time. A bright day can still feel cold. We use safe records or a grown-up’s weather report, not direct Sun watching.~Does a bright day have to be hot?~No~Yes~Only if there are clouds~Draw a cold bright day and a warmer cloudy day.
`);
unit(1,'Comparing our local world','A scientist looks closely, asks questions and records what they notice. We can practise with pictures and safe familiar things. A careful answer says what we actually saw.',
 ['Two children describe the same object differently. What helps?','Look again together and compare details','Choose the louder child','Hide the object','Looking again can help us check a description. A reason matters more than a loud voice.'],`
Sorting by colour~sort~put things into groups using a feature~Red leaves and green leaves can be put into colour groups. We need one clear rule. The same leaves could be sorted another way, such as by shape.~What rule is used in red and green groups?~Colour~Weight~Age~Draw six pretend leaves and sort them by colour.
Sorting by shape~shape~the form or outline of something~A round leaf and a long leaf have different shapes. Changing the sorting rule can change the groups. A shape group need not match a colour group.~Which pair describes shapes?~Round and long~Hot and cold~Loud and quiet~Draw six leaf outlines and circle a group with similar shapes.
Counting what we notice~count~find how many things there are~A count tells us how many. Count each item once, and point to it as you go. Counting a picture does not tell us how many are in every garden.~How should you count each item?~Once~Twice~Only if you like it~Draw five flowers and count them using marks.
Looking over time~change~a difference between one time and another~A plant can change as it grows. Two dated drawings help us compare earlier and later. One drawing alone cannot show how it changed.~What helps show a plant’s change?~Drawings from two dates~One undated drawing~The colour of the notebook~Draw an imagined small seedling and the same plant later.
Questions we can check~question~something we want to find out~A question such as which leaf is longer can be checked by comparing leaves. A question about a favourite leaf asks for a preference. These are different kinds of question.~Which question can be checked by comparing lengths?~Which leaf is longer?~Which leaf is your favourite?~Which leaf has the nicest name?~Draw two leaves and write a question about their lengths.
Keeping a clear record~record~a note or picture of what we found~A labelled picture can show an observation. Write or say what you noticed, not what you wish happened. A made-up example should be called made-up.~What belongs in an observation record?~What you actually noticed~An invented result called real~Only a friend’s favourite answer~Make a labelled observation drawing of one safe familiar object.
`);

unit(2,'Living, dead and never alive','Living things need suitable conditions. Some things were once alive, while others have never been alive. A still object is not enough evidence to decide: plants do not walk, but they are alive.',
 ['How could we check if a bare tree is alive?','Look for buds and changes over time','Say it is dead because it is still','Paint it green','Buds and later growth are useful clues. A winter tree may be alive without leaves.'],`
Living plants~living~carrying out the processes of life~A growing plant is living. It takes in water and grows over time. Plants do not walk, so walking is not a rule for all living things.~Can a plant be living without walking?~Yes~No~Only at night~Draw a growing plant and label one sign that it is alive.
Things once alive~dead~no longer living after once being alive~A fallen leaf came from a living plant. A piece of wood came from a tree. These are different from a rock, which was never alive.~Which came from a living thing?~A wooden block~A metal coin~A glass marble~Sort drawings of a leaf, rock and wooden chair into once-alive or never-alive.
Things never alive~never alive~not living and not once living~A stone and a glass bottle are not living things. They have never carried out life processes. Movement alone is not proof of life: a rolling stone can move.~Which thing has never been alive?~A glass bottle~A fallen leaf~A dead insect~Draw a moving toy car and explain why movement alone is not life.
Growing is a clue~growth~an increase or development in a living thing~A seedling can grow taller and make new leaves. We can look over several days. One quick look cannot show a slow change.~What helps show a seedling’s growth?~Measurements over several days~One quick glance~The colour of the pot only~Draw an imagined seedling on three dates and compare its height.
Living things have needs~need~something important for survival~Animals need air, food and water. Plants need suitable conditions too. A habitat can provide these needs, though different living things need different conditions.~Which set contains basic animal needs?~Air, food and water~Toys, paint and coins~Sun hats, wheels and bells~Make a picture needs-list for a rabbit without handling one.
A dormant seed~dormant~alive but not actively growing~A dry seed may be alive without growing yet. Suitable water and temperature can help it begin growing. Being small and still does not mean it was never alive.~Can a seed be alive before it begins growing?~Yes~No~Only if it has a flower~Draw a seed and a seedling and label the change.
`);
unit(2,'Habitats and food chains','A habitat is where a living thing lives. It provides resources such as food, water and shelter. Animals and plants are connected, so a change can affect more than one living thing.',
 ['What could help compare two habitats?','Record the shelter and living things in each','Move every animal to one place','Guess from the habitat’s name','Comparing the same features gives useful evidence. Leave wild living things undisturbed.'],`
A woodland habitat~habitat~the place where a living thing lives~A woodland has trees and many other living things. Trees can provide food and shelter. Different parts of a woodland have different light and moisture.~What can trees provide for woodland animals?~Food and shelter~Electric sockets~School books~Draw a woodland and label two places that could provide shelter.
A pond habitat~pond~a small area of still water~A pond can support plants and animals suited to water. Some animals also use nearby land. A pond is not the right home for every animal.~Which animal is suited to a pond habitat?~A pond snail~A camel~A polar bear~Draw a pond from a picture and label water and nearby land.
Tiny habitats~microhabitat~a small habitat within a larger one~A space under a log is a microhabitat. It can be damp and sheltered. Woodlice may live there; do not lift heavy logs or disturb animals to study them.~Which is a microhabitat?~Under a log~The entire ocean~The whole planet~Draw the small damp space under an imagined log.
Food from plants~food chain~a way to show who eats what~A caterpillar may eat a leaf, and a bird may eat the caterpillar. A simple chain connects leaf, caterpillar and bird. It shows feeding, not friendship.~In leaf → caterpillar → bird, what does the bird eat?~The caterpillar~The leaf directly~The arrow~Draw the chain with arrows from food towards its eater.
Food and shelter together~shelter~a place offering protection~A hedge can provide shelter and food such as berries. Different animals use it differently. Removing a hedge can remove more than one useful resource.~Why might a hedge matter to an animal?~It can provide food and shelter~It makes all animals identical~It replaces the need for water~Draw a hedge and mark one food source and one sheltered place.
Habitats can change~depend~need or rely on something~Drying a pond changes water available to its living things. An animal’s needs do not disappear when its habitat changes. We can describe a likely effect without claiming every animal responds alike.~What can happen when a pond dries?~Water habitat becomes smaller~All animals stop needing water~The pond becomes deeper~Draw a pond before and after a long dry period.
`);
unit(2,'Seeds, bulbs and plant growth','Plants change over time. Seeds and bulbs contain stores that help early growth. Later, a healthy green plant needs light, water and suitable conditions; not all plants need the same amount.',
 ['How can a plant-height comparison be clearer?','Measure from the same starting point each time','Change the ruler each day without checking','Guess only the tallest plant','Using the same method makes height records easier to compare.'],`
Seeds beginning to grow~germination~when a seed starts to grow~A seed starts to grow when conditions suit it. Many seeds need water and a suitable temperature, but not light, to germinate. A growing seedling later needs light.~Do most seeds need light to start germinating?~No~Yes; always~Only blue light~Draw a seed and a root appearing during germination.
Bulbs store supplies~bulb~an underground plant part with a food store~A bulb contains stored food for early growth. A daffodil can grow from a bulb. A bulb and a seed are different plant structures.~What helps a bulb’s early growth?~Its stored food~A metal battery~Its petals making wind~Draw a bulb with a shoot and label the food store.
Water for plants~water~a liquid that living things need~A plant needs water to stay healthy. Different plants need different amounts. Giving more and more water is not always better; waterlogged roots can have problems.~Does more water always mean healthier growth?~No~Yes~Only if the pot is red~Draw two imaginary plant-care notes for plants with different water needs.
Light for green plants~light~energy that helps green plants make food~Green plants use light to help make food. A seed’s food store does not last forever. We can compare growth using records without harming a real plant.~Why does a growing green plant need light?~To help make food~To hear sounds~To turn soil into metal~Draw a seedling with leaves and label light reaching them.
A suitable temperature~temperature~how hot or cold something is~Plants grow best within suitable temperature ranges. Very cold or very hot conditions can limit growth. Suitable does not mean the hottest possible place.~What does suitable temperature mean?~Conditions that suit that plant~The hottest temperature possible~Any temperature is equally good~Draw a plant-care card that includes water, light and temperature.
Measuring growth over time~height~how tall something is~A plant’s height can be recorded on different dates. Use the same units and starting point. A taller plant is not always the healthiest, so also notice leaves and colour.~What makes height records easier to compare?~Using the same units~Changing units without labels~Leaving out the dates~Make an imagined three-date growth table and clearly label it example data.
`);
unit(2,'Animals grow and change','Young animals are offspring. Some resemble their adults, while others change greatly. Use pictures to compare life stages; animals should not be collected or kept for the paper tasks.',
 ['How can we compare an animal’s life stages?','Put labelled stage pictures in order','Choose pictures only by colour','Assume every animal develops alike','Stage pictures help us compare growth. Different animals can have different life cycles.'],`
Young mammals~offspring~the young of a living thing~A lamb is a young sheep. It grows into an adult sheep. Young mammals need care, though care differs between species.~What does a lamb grow into?~A sheep~A frog~A butterfly~Draw a lamb and adult sheep and label one size difference.
Egg, chick and chicken~hatch~come out of an egg~A chick hatches from an egg and grows into an adult chicken. It does not become a different kind of animal. The adult has larger, more developed body parts.~What comes after an egg in a chicken’s life cycle?~A chick~A tadpole~A pupa~Draw the egg, chick and adult chicken in order.
Frog life stages~tadpole~a young frog stage that lives in water~A frog’s life cycle includes eggs, tadpoles and adult frogs. Tadpoles change as they develop legs. A tadpole is not a baby fish.~Which young stage belongs to a frog?~Tadpole~Chick~Lamb~Draw eggs, a tadpole and a frog in sequence.
Butterfly life stages~pupa~the stage between caterpillar and adult butterfly~A butterfly’s life cycle includes egg, caterpillar, pupa and adult. The caterpillar is a feeding stage. A caterpillar does not simply become a bigger caterpillar forever.~Which stage comes between caterpillar and adult butterfly?~Pupa~Chick~Tadpole~Draw four butterfly life-stage boxes linked in order.
Growing humans~adult~a grown person~Humans grow from babies through childhood and adolescence into adults. People grow at different rates. We do not judge someone’s worth by their height or compare private body information.~Which stage usually follows childhood?~Adolescence~A pupa stage~An egg stage~Draw a fictional person’s life-stage timeline without personal measurements.
Comparing life cycles~life cycle~the stages in a living thing’s life~A chick resembles a small chicken more than a tadpole resembles a frog. Both grow and develop. Similarities and differences can be shown in a picture table.~Which comparison is useful?~Compare the same life stages~Compare only favourite colours~Assume all young look exactly like adults~Make two rows comparing chicken and frog life stages.
`);
unit(2,'Keeping healthy','Bodies need care. Food, water, activity, rest and hygiene matter. People have different needs and abilities. These lessons explain science; a trusted grown-up helps with personal health questions.',
 ['How could a handwashing picture sequence be checked?','Compare it with reliable grown-up guidance','Choose the prettiest picture','Skip steps that seem boring','A reliable sequence helps us check the order. Looking clean does not mean hands have no microbes.'],`
Water, food and air~survival~staying alive~Animals, including humans, need water, food and air. Food provides energy and materials for growth. A toy is enjoyable but is not a basic survival need.~Which is a basic survival need?~Water~A toy robot~A television~Draw a human needs chart with water, food and air.
Different foods~variety~a range of different things~Different foods provide different nutrients. A varied diet includes suitable amounts of different foods. One favourite food cannot provide every need by itself.~Why do we eat a variety of foods?~Foods provide different nutrients~All foods contain exactly the same things~Colour alone decides nutrition~Draw an imaginary varied meal; ask a grown-up about personal dietary needs.
Moving our bodies~exercise~activity that works the body~Activity helps keep bodies healthy. People can move in different ways, including seated activities. A safe activity should suit the person’s ability and grown-up guidance.~Can people exercise in different ways?~Yes~No; only running counts~No; only winning counts~Draw two different ways a person could safely be active.
Rest and sleep~rest~time for the body to recover~Sleep and rest help bodies function. Feeling tired is a reason to tell a grown-up. People need both activity and recovery, rather than nonstop exercise.~Do bodies need recovery as well as activity?~Yes~No~Only after winning a race~Make a fictional daily picture plan containing play and rest.
Washing hands~hygiene~habits that help keep us clean~Handwashing helps remove dirt and microbes. Hands can carry microbes even when they look clean. Soap, water and proper washing matter; a quick dry wipe is not the same.~Can clean-looking hands still carry microbes?~Yes~No~Only if they are painted~Draw a handwashing reminder poster without using chemicals.
Caring for teeth~tooth~a hard structure used for biting and chewing~Teeth help us bite and chew food. Cleaning them helps care for them. We use a grown-up’s guidance and dental advice rather than trying homemade treatments.~What is one job of teeth?~Biting and chewing~Hearing~Pumping blood~Draw a smile and label a tooth’s job without inspecting anyone else’s mouth.
`);
unit(2,'Choosing and changing materials','A useful material has properties that suit a job. Changing an object’s shape does not always make a new material. Compare safe pictures or paper; do not break, heat or taste objects.',
 ['What helps choose a material for a raincoat?','Compare how well it keeps water out','Choose only the longest name','Choose the softest material without considering water','A raincoat needs properties suited to rain. More than one property can matter.'],`
Waterproof choices~waterproof~not easily letting water pass through~A waterproof outer layer can help keep rain out. Absorbent cloth takes water in. These are different properties, so the best material depends on the job.~Which property suits a raincoat’s outer layer?~Waterproof~Absorbent only~Dissolves quickly in rain~Draw a raincoat and label the property needed for rain.
Absorbing a spill~absorbent~able to take liquid into itself~A towel can absorb water. A plastic sheet usually does not absorb water in the same way. A useful towel and a useful raincoat need different properties.~Which property helps a towel dry a spill?~Absorbent~Transparent~Magnetic~Draw a towel and a raincoat with their different jobs.
Stiff and flexible~flexible~able to bend without easily breaking~Some objects bend easily; others are stiff. A flexible bag and a stiff box can both be useful. Thickness and shape can affect how an object bends.~Which word describes something that bends easily?~Flexible~Transparent~Absorbent~Draw a bendy bag and a stiff box and label each.
Squashing and bending~bend~change the direction or shape of an object~A safe paper strip can bend. It is still paper afterwards. A change in shape alone does not necessarily create a new material.~Does bending paper make it stop being paper?~No~Yes~Only on Tuesdays~Bend a sheet of paper gently, then draw its new shape.
Twisting and stretching~stretch~make something longer by pulling~Some materials stretch more than others. Stretching changes shape or length, but not always the material. Do not stretch objects near faces or use elastic for this task.~What does stretching change first?~Shape or length~The day of the week~An object into an animal~Draw an imagined stretchy fabric before and after stretching.
One job, different materials~suitable~well matched to a purpose~A spoon can be made from metal, wood or plastic. Different choices have advantages for different jobs. Naming a material is not enough; explain the property that helps.~How should a material choice be explained?~Link its property to the job~Give only its colour~Assume one material is best for everything~Design a spoon on paper and label one useful material property.
`);

unit(3,'Flowering plants and their jobs','Plant parts work together. A plant needs suitable conditions, but its needs differ from an animal’s. Use labelled diagrams to connect each structure with its function.',
 ['How could we compare plant growth with different light?','Keep other conditions similar and record growth','Change water and light together without recording','Choose the plant you like best','Changing one factor makes its effect easier to investigate. A school-grown comparison needs adult care.'],`
Roots and absorption~absorb~take a substance into something~Roots absorb water and mineral nutrients. They also anchor many plants. Roots do not simply drink ready-made food from the soil.~What do roots absorb?~Water and mineral nutrients~Ready-made leaves~Sunlight underground~Draw roots and arrows showing water entering a plant.
Water through a stem~transport~move something from one place to another~Water moves from roots through a plant’s stem. The stem supports leaves and flowers too. A transport diagram shows direction, not the exact size of water particles.~Which part carries water upwards from roots?~Stem~Petal only~Seed coat only~Draw the route from roots through stem to leaves.
Leaves making food~function~the job of a structure~Green plants use light to make food in their leaves and other green parts. Soil supplies mineral nutrients, not the plant’s entire food supply. Plants need air as well.~What helps green leaves make food?~Light~Darkness alone~A diet of insects for every plant~Draw a leaf with labels for light, air and water.
Pollination~pollination~transfer of pollen to the receiving part of a flower~Pollen moves between the relevant flower parts. Insects or wind can help, depending on the plant. Pollination is not the same as scattering a finished seed.~What is moved during pollination?~Pollen~A finished tree~A rock~Draw an insect carrying pollen between two imaginary flowers.
Seeds forming~seed~a plant structure containing a young plant and food store~After suitable pollination and fertilisation, flowering plants can form seeds. A fruit can contain seeds. A seed and pollen are different stages in reproduction.~What can a fruit contain?~Seeds~Only roots~Only pollen grains~Draw an opened fruit from a picture and label its seeds.
Seed dispersal~dispersal~spreading away from a starting place~Seeds can be spread by wind, water or animals. Dispersal can reduce crowding near the parent. Different seed shapes suit different ways of travelling.~Why can dispersal help a young plant?~It can reduce crowding near the parent~It stops all need for water~It makes every seed identical~Design two paper seed drawings suited to different dispersal methods.
`);
unit(3,'Nutrition, skeletons and muscles','Animals get food by eating other organisms or their products. Skeletons support and protect many animals. Muscles and joints help movement; a diagram is a simplified view of the body.',
 ['How should two animal skeleton pictures be compared?','Compare corresponding body parts','Compare only picture size','Assume bigger drawings mean bigger real bones','Compare the same structures and check diagram labels. Pictures may use different scales.'],`
Food provides nutrients~nutrient~a substance needed by a living thing~Different nutrients have different jobs. Animals obtain them from food. A varied suitable diet provides energy and materials, rather than one nutrient doing everything.~Where do animals get nutrients?~Food~Sunlight alone~Stone alone~Draw a food-to-body diagram and label energy and growth materials.
Energy and growth~protein~a nutrient used for growth and repair~Protein supports growth and repair. Carbohydrates and fats can provide energy. Foods contain mixtures of nutrients, so one food is not always one nutrient.~Which nutrient supports growth and repair?~Protein~Light~Sand~Make a paper chart linking protein, carbohydrates and fats to their roles.
Skeleton support~skeleton~a framework supporting an animal’s body~The human skeleton supports the body and protects important organs. Bones are living structures. A skeleton is not only a prop for standing still.~What does a skeleton provide?~Support and protection~All the body’s food~The air around the body~Draw a body outline and mark support from bones.
Skull and ribs~protect~help keep something from damage~The skull helps protect the brain. The rib cage helps protect the heart and lungs. Different bones have different shapes suited to their jobs.~Which structure helps protect the brain?~Skull~Finger bones~Kneecap~Draw a skull and rib cage with the organs they protect labelled.
Muscles pull~muscle~tissue that contracts to produce movement~Muscles contract and pull. Many work in pairs around a joint. A muscle does not push a bone in the same way that a hand pushes a door.~How does a contracting muscle move a bone?~By pulling~By turning into air~By making the bone disappear~Draw a bending arm with a muscle pair shown as a simple model.
Animals without backbones~invertebrate~an animal without a backbone~A worm is an invertebrate. A crab has a hard outer skeleton but no backbone. Not having a backbone does not mean having no support at all.~Which animal has no backbone?~A crab~A cat~A human~Compare a crab and cat picture and label outer and inner support.
`);
unit(3,'Rocks, fossils and soil','Rocks have different textures and properties. Some contain evidence of past life. Soil contains rock particles and organic material. Study pictures; unknown stones and soil should not be handled or tasted.',
 ['What helps compare two rock pictures?','Use the same features such as grains and layers','Decide only from favourite colour','Assume all shiny rocks are identical','Texture and structure give clues. A picture alone may not identify every rock reliably.'],`
Rock textures~texture~the size and arrangement of grains in a material~A rock can have visible grains or crystals. Colour alone may not identify it. Describe several features before choosing a group.~Which feature can help describe a rock?~Its grains~Its favourite food~Its voice~Draw two imagined rocks with different grain textures.
Igneous rock~igneous~formed when molten rock cools~Molten rock can cool and become igneous rock. Cooling conditions affect crystal size. A rock’s formation cannot be decided just by calling it hard.~How does igneous rock form?~Molten rock cools~A leaf grows~A cloud freezes into wood~Draw molten rock cooling into a solid rock as a labelled sequence.
Sedimentary layers~sedimentary~formed from sediments joined over time~Sediments can collect in layers and become rock. Many fossils are found in sedimentary rocks. Layered does not mean every layer contains a fossil.~What can form sedimentary rock?~Layers of sediment~Growing feathers~Only metal coins~Draw sediment layers and label older and newer layers in a simple undisturbed model.
Metamorphic change~metamorphic~rock changed by heat and pressure without melting~Heat and pressure can change a rock into metamorphic rock. It remains solid during this process. Melting and cooling would describe a different route.~Does metamorphic change require the rock to melt?~No~Yes~Only if it is dark~Draw a rock-change arrow labelled heat and pressure, without heating anything.
Fossil formation~fossil~preserved remains or traces of past life~Remains or traces can be buried and preserved over time. Most living things do not become fossils. A footprint fossil is a trace, not a whole preserved animal.~Which can be a trace fossil?~A preserved footprint~A new toy dinosaur~A drawing made today~Draw a footprint being covered by sediment in a labelled model.
Soil ingredients~organic matter~material from living or once-living things~Soil contains rock particles, organic matter, air and water. It is not just ground-up rock. Different soils contain different proportions of these ingredients.~Which belongs in soil?~Rock particles and organic matter~Only plastic~Only metal~Draw a magnified soil model and label its main ingredients.
`);
unit(3,'Light and shadows','We need light to see. Light can come from a source or be reflected from an object. Use diagrams and safe indoor observations. Never look directly at the Sun or point bright lights at eyes.',
 ['How can a shadow-size comparison be planned fairly?','Change one distance and keep other things the same','Change every object and distance together','Measure only the nicest shadow','Keeping the object and light source the same helps investigate distance. The paper plan needs no bright light.'],`
Sources of light~source~something that produces light~The Sun and a switched-on lamp produce light. The Moon reflects sunlight; it does not make its own visible light. A bright-looking object is not always a source.~Which object reflects sunlight rather than producing its own visible light?~The Moon~The Sun~A lit lamp~Draw two light sources and the Moon; label source or reflector.
Seeing objects~reflect~send light back from a surface~Light from a source reaches an object and some is reflected towards our eyes. We cannot see an ordinary object in complete darkness. Eyes do not send out seeing rays.~Why can we see an ordinary object?~Light reaches our eyes from it~Eyes shoot light at it~It must make its own light~Draw arrows from lamp to book to eye in a simple model.
Darkness and light~darkness~absence of light~Darkness means there is little or no light. It is not a substance flowing from a dark object. A source can illuminate a space.~What does complete darkness mean?~No light is available~Black paint fills the air~Eyes make darkness~Draw an unlit room and the same room with a lamp switched on.
Opaque objects~opaque~not allowing light through~An opaque object blocks light. A shadow forms where light from a source is blocked. A shadow is not a stain on the surface.~What forms a shadow?~Light being blocked~Light being eaten~A surface changing material~Draw a light source, opaque object and shadow on paper.
Transparent and translucent~translucent~letting some light through without a clear view~A clear window is transparent. Frosted glass can be translucent. An opaque wall blocks light; these words describe how materials let light through.~Which word fits frosted glass that passes light but blurs a view?~Translucent~Opaque~Magnetic~Draw three windows labelled transparent, translucent and opaque.
Shadow size patterns~distance~how far apart things are~For a fixed light source and screen, moving an object closer to the source can enlarge its shadow. A fair comparison keeps other things fixed. This is a prediction to check, not a universal result for every setup.~What should stay fixed when comparing object distance and shadow size?~The light source and screen~Every distance should change~The object’s shape must change~Draw two labelled shadow setups with one changed distance.
`);
unit(3,'Contact forces and surfaces','A push or pull is a force. Contact forces need things to touch. Surface properties affect motion, but careful comparisons also consider the object and how it is pushed.',
 ['How could toy-car travel on two surfaces be compared?','Use the same car and starting push or slope','Use a different car and push each time','Choose only the farther result','A consistent car and start help compare surfaces. A paper plan can identify what to control.'],`
Pushes and pulls~force~a push or pull on an object~A force can change an object’s motion or shape. Opening a door involves a push or pull. Movement alone does not tell us which forces are acting.~Which action is a force?~Pulling a door~Naming a door~Looking at its colour~Draw a door with a push or pull arrow.
Contact between objects~contact~touching between objects~A hand pushing a ball touches it. This is a contact force. Some forces, such as magnetism, can act without contact.~Which is a contact force?~A hand pushing a ball~A magnet attracting at a distance~Earth’s gravity~Draw two touching objects and label the force arrow.
Friction on surfaces~friction~a contact force opposing sliding~Friction acts when surfaces slide or try to slide. It often slows a sliding object. Friction also helps shoes grip, so it is not always unwanted.~What can friction help shoes do?~Grip the ground~Float in air~Become lighter~Draw a shoe on the ground and label a useful effect of friction.
Different travel distances~compare~look for similarities and differences~The same car can travel different distances on different surfaces. A measurement is stronger evidence than calling one surface best. Other differences must be considered too.~What is useful evidence in a car-travel comparison?~Measured travel distance~The car owner’s name~The nicest colour~Make an example table for two surfaces and clearly mark the numbers invented.
Forces can change shape~deform~change an object’s shape~A force can bend or squash an object. It need not make the whole object travel. Gentle bending of paper is a safe example.~Can a force change shape without moving an object far?~Yes~No~Only magnets can~Fold paper gently and draw its changed shape.
Checking a repeated result~repeat~do a measurement again~A repeated comparison helps reveal how much results vary. One result can be unusual. Repetition does not mean choosing only the result we wanted.~Why repeat a travel comparison?~To see how results vary~To hide an unwanted result~To change the question each time~Plan three repeat rows in a surface-comparison table.
`);
unit(3,'Magnets and poles','Magnetic forces can act without touching. Not every metal is attracted strongly to a classroom magnet. These activities use drawings; small magnets are not needed and must never be swallowed.',
 ['How should a claim that all metals are magnetic be checked?','Compare several named metals using reliable evidence','Test one metal and assume all agree','Use colour as the only test','Iron and aluminium do not respond alike. A single example does not establish a rule for all metals.'],`
Magnetic attraction~attract~pull towards something~A magnet can attract certain materials at a distance. Iron is a familiar example. It does not attract all materials in the same way.~Which material is attracted strongly by an ordinary magnet?~Iron~Wood~Glass~Draw a magnet attracting an iron nail, without using real magnets.
Not all metals~magnetic~responding to a magnetic field~Iron and many steels are attracted to magnets. Aluminium is not strongly attracted by an ordinary classroom magnet. Being metal is not enough to predict strong attraction.~Which metal is not strongly attracted by an ordinary classroom magnet?~Aluminium~Iron~Many steels~Make a paper sorting chart for iron, aluminium, wood and glass.
Two magnetic poles~pole~one of a magnet’s two magnetic ends~A bar magnet has north and south poles. These names do not mean the ends are made of different colours. Paint is a label, not the cause of magnetism.~How many poles does a bar magnet have?~Two~One~None~Draw a bar magnet and label N and S.
Like poles repel~repel~push away from another object~Two north poles repel; two south poles repel too. The force can act without contact. Repulsion is different from attraction.~What do two north poles do?~Repel~Always attract~Have no magnetic interaction~Draw two north poles facing and arrows showing repulsion.
Unlike poles attract~unlike~different in the feature being compared~A north and south pole attract. Which poles face each other affects the interaction. Turning one magnet changes the facing poles.~What do a north and south pole do?~Attract~Always repel~Turn into wood~Draw opposite poles facing with arrows showing attraction.
A magnet’s useful job~prediction~what we expect based on evidence~A magnetic catch can help hold a door closed. Its design uses attraction. A prediction should mention the magnetic materials, rather than assume any door will stick.~Why can a magnetic catch hold a suitable door closed?~Magnetic attraction~The paint colour~The door’s name~Design a paper magnetic catch and label the attracting parts.
`);

unit(4,'Classification and changing habitats','Living things can be grouped in several ways. A classification key uses features to identify a group. Habitat change can affect living things positively or negatively; evidence is needed for the particular place.',
 ['What makes a useful yes-or-no key question?','A feature that can be checked','A favourite animal name','A guess about whether an animal is nice','A visible, clear feature helps different people use the same key.'],`
Vertebrate groups~vertebrate~an animal with a backbone~Fish, amphibians, reptiles, birds and mammals are vertebrates. Their features differ. A habitat alone cannot identify the group: whales and fish both live in water.~Which animal is a vertebrate?~A frog~An earthworm~A spider~Draw a five-group vertebrate chart with a pictured example for each.
Insects and spiders~insect~an animal with six legs and three main body sections~Adult insects have six legs; spiders have eight. Both are invertebrates. A spider is not an insect just because it is small.~How many legs does an adult insect have?~Six~Eight~Four~Draw a beetle and spider and label the different leg counts.
Flowering and non-flowering plants~flowering plant~a plant that produces flowers for reproduction~Grasses are flowering plants, even when their flowers are small. Ferns do not make flowers. A bright petal is not required for every flower.~Which is a flowering plant?~Grass~A fern~A moss~Draw a grass flower model and a fern, clearly using picture references.
Using a branching key~key~a sequence of questions used to identify something~A key splits a set into smaller groups using features. Each answer sends us to another question or name. A key only covers the organisms included in it.~What does a classification key use?~Feature questions~Only favourite colours~Only guesses~Make a key to separate a bird, fish and spider from pictures.
Habitat damage~environment~the surroundings of a living thing~Litter, pollution or removal of vegetation can change a habitat. Effects depend on the organisms and the change. We should not disturb a habitat to investigate it.~What could remove shelter from a habitat?~Cutting down its vegetation~Making a picture record~Reading a nature guide~Draw a habitat before and after an imagined loss of shelter.
Helping a habitat~conservation~protecting living things and their habitats~A well-planned reserve can protect habitat. Different organisms need different conditions. Helping one species should include considering effects on other species.~What should habitat protection consider?~The needs of living things there~Only the colour of a sign~Only one favourite animal~Plan a paper wildlife area with food, shelter and water labelled.
`);
unit(4,'Teeth and digestion','Digestion breaks food down so useful substances can be absorbed. The mouth, stomach and intestines have different jobs. A body diagram is a simplified model and should be labelled clearly.',
 ['What helps compare animal teeth?','Compare tooth shape and known diet','Assume bigger teeth mean a kinder animal','Judge diet from colour alone','Shapes provide clues about biting and grinding, alongside reliable information about diet.'],`
Incisors for cutting~incisor~a front tooth used for biting and cutting~Incisors help bite and cut food. Tooth shapes suit different jobs. Not every tooth in a mouth has the same shape.~What is an incisor used for?~Biting and cutting~Hearing~Pumping blood~Draw front teeth and label their cutting job.
Canines and molars~molar~a back tooth used for grinding~Canines help grip or tear food; molars help grind it. Chewing makes pieces smaller. Teeth do not absorb most of the nutrients into blood.~What do molars help do?~Grind food~Make blood~Hear sound~Draw canine and molar shapes with their jobs labelled.
Mouth and saliva~saliva~fluid in the mouth that moistens food and helps digestion~Chewing and saliva begin processing food. Saliva moistens food and contains substances that start breaking down starch. Digestion begins before food reaches the stomach.~Where does digestion begin?~The mouth~The large intestine only~The heart~Draw food entering a mouth and label chewing and saliva.
Oesophagus and stomach~oesophagus~the tube carrying food from mouth to stomach~Food travels down the oesophagus. The stomach mixes food and digestive fluids. It is not where every useful nutrient is absorbed.~Which tube carries food to the stomach?~Oesophagus~Windpipe~A blood vessel~Draw the mouth, oesophagus and stomach in order.
Small intestine absorption~absorption~movement of digested substances into the body~Most nutrient absorption happens in the small intestine. Digestion and absorption are related but different. Food is broken down, then useful substances can enter the blood.~Where are most digested nutrients absorbed?~Small intestine~Teeth~Lungs~Draw a small intestine with arrows labelled nutrients into blood.
Large intestine and food chains~consumer~an organism that obtains food by eating~The large intestine absorbs water and helps form waste. Animals are consumers in food chains. Plants usually begin a chain by making food, rather than eating another organism.~Which organism is a consumer?~A rabbit~Grass~An oak leaf~Draw grass → rabbit → fox and label the consumers.
`);
unit(4,'States of matter','Solids, liquids and gases behave differently. A substance can change state. These lessons use diagrams, not heating or chemical experiments; a change in state does not necessarily make a new substance.',
 ['How can melting temperatures be compared safely here?','Use a reliable labelled data table','Heat unknown objects at home','Guess from colour','Reading known data avoids unsafe heating. State the substance and units in the comparison.'],`
Solids keep shape~solid~a state that keeps its own shape and volume~A solid usually keeps its shape unless a force changes it. Sand consists of many small solid grains. Pouring sand does not make each grain a liquid.~What are sand grains?~Small solids~Tiny liquids~A gas~Draw sand grains in a jar and label the grains solid.
Liquids take container shape~liquid~a state with fixed volume but no fixed shape~A liquid takes the shape of its container. A fixed amount of water can look different in a tall cup and a wide bowl. Its amount has not changed just because its level differs.~What changes when water is poured into a different-shaped container?~Its shape~Its identity as water~Its amount must double~Draw the same water amount in two differently shaped containers.
Gases spread out~gas~a state that spreads to fill available space~Air is a mixture of gases. Gases can spread through available space. An apparently empty cup usually contains air, not nothing.~What is usually inside an apparently empty cup?~Air~Nothing at all~Solid ice~Draw a cup with dots representing gas particles; label it a model.
Melting and freezing~melting~a solid changing to a liquid~Ice melts into liquid water. Liquid water can freeze into ice. The substance remains water, even though its state changes.~What does ice become when it melts?~Liquid water~A new metal~Oxygen only~Draw solid ice and liquid water linked by melting and freezing arrows.
Evaporation from a surface~evaporation~liquid changing to gas at its surface~Liquid water can evaporate below boiling temperature. A puddle can dry without boiling. Water vapour is a gas and is usually invisible.~Does evaporation require boiling?~No~Yes~Only outdoors~Draw a puddle becoming smaller and label water vapour entering the air.
Condensation~condensation~a gas changing to a liquid~Water vapour can condense into liquid droplets on a cool surface. The droplets did not pass through solid glass. The visible droplets are liquid, not water vapour gas.~What forms when water vapour condenses?~Liquid droplets~Dry sand~A new gas~Draw droplets on the outside of an imagined cool glass.
`);
unit(4,'The water cycle','Water moves between places and states. The Sun provides energy for much evaporation. A simple cycle diagram leaves out many routes and timescales, so it is a model rather than a complete map.',
 ['How should a water-cycle diagram be read?','Follow labelled processes and arrows','Assume each drop takes exactly the same route','Assume the drawing is to scale','The diagram shows connections. Real water can follow many routes and take different amounts of time.'],`
Evaporation in the cycle~water vapour~water in its gas state~Water evaporates from seas, lakes and other surfaces. Energy helps this happen. Visible mist contains tiny liquid droplets; it is not simply visible gas.~What is water vapour?~Water gas~Tiny dry stones~Only visible cloud droplets~Draw evaporation arrows from a lake into the air.
Cloud droplets~cloud~many tiny water droplets or ice crystals in air~Cooling air can lead water vapour to condense. Clouds contain tiny droplets or ice crystals. A cloud is not a bag full of only water gas.~What can a cloud contain?~Tiny droplets or ice crystals~Only rocks~Only invisible water gas~Draw a magnified cloud model with tiny droplets labelled.
Rain and other precipitation~precipitation~water falling from clouds as rain, snow or hail~Droplets or ice particles can grow and fall. Rain, snow and hail are kinds of precipitation. Not every cloud produces rain at a given moment.~Which is precipitation?~Snow~Sunlight~Wind alone~Draw three labelled precipitation symbols.
Water running downhill~runoff~water flowing over land~Rainwater can flow over land into streams and rivers. Gravity helps water move downhill. Some water enters the ground instead of staying on the surface.~What is runoff?~Water flowing over land~Water becoming a metal~Clouds making sunlight~Draw a hill and stream with runoff arrows.
Water underground~infiltration~water entering the ground~Some rainwater enters spaces in soil and rock. Underground water can move slowly. A simple surface-water picture does not show all stored water.~Where does infiltrating water go?~Into the ground~Only upwards into stars~Into solid iron~Draw rain entering soil and label underground water.
Temperature and drying~variable~something that can change in an investigation~Warmer conditions can increase evaporation, but wind and humidity also matter. Comparing drying needs more than noting the season. Control or record relevant conditions.~Which other condition can affect drying besides temperature?~Wind~The notebook’s title~The observer’s favourite colour~Plan a paper drying comparison and list temperature, wind and starting water.
`);
unit(4,'Sound and vibration','Sound is produced by vibrations and travels through a medium. Ears detect vibrations. Work with pictures and ordinary quiet sounds; do not create loud noises or put objects into ears.',
 ['How could pitch be compared on a model instrument?','Change one feature and describe pitch','Change every feature and choose the loudest','Use picture colour as evidence','A planned comparison separates pitch from loudness and avoids unnecessarily loud sounds.'],`
Vibrating sources~vibration~a repeated back-and-forth movement~A vibrating object can produce sound. A plucked string vibrates. We may not see every vibration, but sound production is connected to movement.~What produces sound from a plucked string?~Its vibration~Its colour~Its name~Draw a still string and vibrating string as a labelled model.
Sound through air~medium~a material through which a wave travels~Sound travels through air to our ears. It can also travel through liquids and solids. It needs a medium, unlike light travelling through space.~Can sound travel through solids?~Yes~No~Only if they are transparent~Draw a sound route from a source through air to an ear.
The ear detects sound~eardrum~a membrane in the ear that vibrates with sound~Sound makes parts of the ear vibrate. The body turns signals into what we hear. A drawing of a large wave is a model, not an actual giant shape moving into the ear.~What happens to the eardrum when sound reaches it?~It vibrates~It becomes a tooth~It makes sunlight~Draw a simplified ear route with vibration labelled.
Pitch and vibration rate~pitch~how high or low a sound is~Faster vibrations usually produce a higher pitch. Slower vibrations produce a lower pitch. Pitch is different from loudness.~What usually produces a higher pitch?~Faster vibrations~Slower vibrations~A darker colour~Draw two wave models with different vibration rates.
Loudness and vibration size~volume~how loud or quiet a sound seems~Larger vibrations can produce louder sounds. A loud sound need not have a high pitch. Sound can harm hearing when too loud.~Is a louder sound always higher in pitch?~No~Yes~Only from a drum~Draw quiet and louder wave models with the same spacing.
Sound over distance~distance~separation between a source and listener~A sound usually becomes quieter as a listener moves farther away. Surroundings affect what is heard too. A measurement should state where the listener or sensor was.~What usually happens farther from a sound source?~The sound becomes quieter~The sound always gets louder~The source stops vibrating~Draw a sound source and two listeners at labelled distances.
`);
unit(4,'Simple electrical circuits','A circuit needs a complete conducting path. Use paper circuit diagrams here. Only a trained grown-up should arrange real school circuit equipment; mains sockets, damaged batteries and small button batteries are excluded.',
 ['How should a bulb comparison be recorded?','Show the circuit connections and the observed brightness','Record only the wire colour','Leave out which cell was used','Circuit layout and supply matter. A sketch helps explain an observation without touching mains electricity.'],`
Electrical appliances~appliance~a device designed for a job~Some appliances use mains electricity; others use batteries. A wire or plug is not an invitation to experiment. Electricity supplies energy for a device’s function.~Which appliance can use a battery?~A torch~A wooden chair~A spoon~Draw a battery-powered torch and label its purpose.
Cells as a supply~cell~a source that can supply electrical energy~A cell can supply a simple circuit. A battery may contain several cells. Cell energy is transferred when there is a complete working path.~What supplies electrical energy in a simple cell circuit?~The cell~Wire colour~The bulb’s label~Draw a cell, bulb and wires as a connected paper circuit.
Complete conducting paths~circuit~a path along which electric current can flow~A bulb can light in a suitable complete circuit. A gap stops current in a simple series circuit. Both cell terminals and both bulb contacts matter.~What happens if a simple series circuit has a gap?~Current stops~Current always doubles~The wire becomes a cell~Draw a complete circuit and an otherwise identical circuit with a gap.
Switches open and close~switch~a component that opens or closes a path~A closed switch completes its part of the path. An open switch makes a gap. The words open and closed describe the circuit connection, not an open room door.~Which switch position permits current in a simple circuit?~Closed~Open~Neither ever~Draw the same circuit with the switch open and closed.
Conductors and insulators~conductor~a material through which current can pass readily~Many metals conduct electricity. Plastic is often used as insulation around wires. A conductor and an insulator have different jobs.~Why is plastic often placed around a wire?~To insulate it~To supply unlimited energy~To make current appear from nothing~Draw a cable cross-section with metal and insulating cover labelled.
Finding a circuit fault~fault~something stopping a system working as intended~A bulb may fail to light because of a gap, poor contact or unsuitable components. One possible cause is not proof of every fault. Inspect a diagram and reason about the path.~What could prevent a bulb lighting in a simple circuit?~A gap in the path~A labelled complete conducting path alone~The paper’s colour~Mark one gap in a deliberately faulty paper circuit and draw the repair.
`);

unit(5,'Life cycles and reproduction','Reproduction produces new living things. Life cycles differ between groups. Compare labelled diagrams and reliable references, without collecting eggs, breeding animals or disturbing plants.',
 ['How can life cycles be compared clearly?','Compare equivalent stages and label differences','Assume all organisms have identical stages','Compare drawing size only','A diagram should identify stages, not suggest all species develop in the same way.'],`
Mammal life cycles~reproduction~production of new organisms~Most mammals give birth to live young, though a few lay eggs. Young mammals receive milk. A rule saying every mammal has live young would miss these exceptions.~Do all mammals give birth to live young?~No; a few lay eggs~Yes; without exception~No; all lay eggs~Draw a typical mammal cycle and add a note that exceptions exist.
Amphibian development~metamorphosis~a major change in body form during development~A frog changes from tadpole to adult. Legs develop and the tail is absorbed. Development is more than becoming larger while keeping an identical body.~Which change happens as a tadpole develops?~Legs develop~Feathers grow~It becomes a fish~Draw a frog cycle and label two changes in form.
Complete insect metamorphosis~larva~an immature feeding stage in some animals~A butterfly larva is a caterpillar. A pupa follows, then the adult. Not all insects have the same stages: grasshoppers lack a pupa stage.~Which insect has a pupa stage?~A butterfly~A grasshopper~Both always have one~Compare a butterfly cycle with a grasshopper cycle on paper.
Bird reproduction~incubation~keeping eggs in suitable conditions for development~Birds lay eggs. Many incubate them using body warmth. A chick develops inside a fertilised egg before hatching; not every egg laid will develop into a chick.~What is incubation for?~Suitable conditions for egg development~Making an egg magnetic~Turning eggs into seeds~Draw egg development and hatching as a labelled sequence.
Sexual reproduction in flowers~fertilisation~joining of male and female reproductive cells~Pollination transfers pollen; fertilisation joins reproductive cells. A seed can then develop. These words describe different events, not two names for the same action.~Is pollination the same as fertilisation?~No~Yes~Only in yellow flowers~Draw flower reproduction with separate pollination and fertilisation labels.
Asexual plant reproduction~asexual~reproduction without joining reproductive cells~Some plants make new plants from runners or other vegetative structures. This is asexual reproduction. Offspring often share the parent’s inherited characteristics closely.~Which is an example of asexual reproduction?~A strawberry runner making a new plant~Pollen fertilising an ovule~A bird laying a fertilised egg~Draw a strawberry parent and new plant connected by a runner.
`);
unit(5,'Human growth and change','Humans change through life. Puberty is part of development towards adulthood, with differences in timing. Discuss fictional examples; nobody needs to share private body details. A trusted grown-up can help with questions.',
 ['How should a growth comparison be interpreted?','Recognise individual differences and use labelled evidence','Rank people’s worth by height','Assume everybody changes on one birthday','Growth varies. A class diagram cannot diagnose an individual or set a single timetable for everyone.'],`
Stages across a lifetime~adolescence~the transition between childhood and adulthood~Humans pass through life stages including infancy, childhood, adolescence and adulthood. Ages and experiences vary. A timeline is a model, not a rule that everyone changes on one day.~Which stage lies between childhood and adulthood?~Adolescence~Infancy~Germination~Draw a fictional life-stage timeline without exact puberty deadlines.
Puberty is development~puberty~body changes towards reproductive maturity~Puberty brings body changes as a person develops towards adulthood. It starts at different times. Differences in timing do not determine someone’s value or maturity in every aspect of life.~Does puberty begin at the same time for everyone?~No~Yes~Only during the summer term~Make a general puberty information card using no personal measurements.
Hormones carry signals~hormone~a chemical messenger in the body~Hormones help coordinate changes during puberty. They are chemical signals, not thoughts. Development involves many body processes working together.~What is a hormone?~A chemical messenger~A bone joint~A food group~Draw a simple message-arrow model between body parts.
Changes in height and skin~growth spurt~a period of relatively rapid growth~Many people grow more quickly during puberty. Skin and body hair can change too. Rates vary, so a fictional growth graph cannot predict an individual’s exact growth.~What is a growth spurt?~A period of faster growth~A guarantee of one exact final height~The same as losing all bones~Draw a labelled fictional growth graph and mark it example data.
Menstruation and body changes~menstruation~shedding of the uterus lining as a period~Puberty can include breast development and periods in people with a uterus. The timing varies. Periods are a normal body process; questions can be taken privately to a trusted grown-up.~What is menstruation?~Shedding of the uterus lining~Food passing into the stomach~Air entering the lungs~Make a respectful word-and-meaning card without personal information.
Voices and reproductive development~development~changes as a body matures~Puberty can include a deeper voice and growth of reproductive organs in people with testes. Other changes happen too. A single feature cannot tell us someone’s exact stage or timetable.~Can one voice change give an exact puberty timetable?~No~Yes~Only if the person is tall~List general development words with a reminder that timing varies.
`,'https://www.nhs.uk/conditions/early-or-delayed-puberty/');
unit(5,'Properties of materials','Material choices depend on measured properties and the intended job. A fair comparison controls relevant variables. Use paper design challenges and published example data, not electrical or heat tests at home.',
 ['What makes an insulation comparison fairer?','Use equal starting conditions and change the tested material','Use different starting temperatures without recording','Pick the most colourful material','Comparable starting conditions help investigate the material rather than an unrelated difference.'],`
Hardness and strength~hardness~resistance to scratching or indentation~Hardness is not the same as strength or toughness. A hard material can still break. Describe which property was tested rather than calling every good material strong.~What does hardness describe?~Resistance to scratching~Ability to see through~Electrical energy supplied~Make a paper property card separating hardness from transparency.
Thermal conductors~thermal conductor~a material that transfers energy by heating readily~Metals often transfer thermal energy readily. A saucepan body uses this property. Its handle may use a less conducting material to reduce transfer to a hand.~Why might a saucepan body be metal?~It transfers thermal energy readily~It stops all energy transfer~It makes food from nothing~Draw a pan and label different body and handle properties.
Electrical material choices~electrical insulator~a material that resists electric current~Insulation around a cable helps prevent unwanted current paths. The metal inside conducts. Knowing a material conducts does not make it safe to touch a powered circuit.~Why is cable covering an insulator?~To resist unwanted current paths~To supply the current~To remove every need for a circuit~Draw a cable model and label conducting core and insulating cover.
Solubility~soluble~able to dissolve in a particular solvent~Some solids dissolve in water and others do not. Solubility depends on the substance, solvent and conditions. A disappearing-looking solid has not necessarily stopped existing.~What does soluble in water mean?~It can dissolve in water~It must melt into water~It ceases to exist~Draw a particle model of a soluble solid spread through water.
Transparency in a design~transparency~how readily a clear view through a material is possible~A clear window needs transparency. A curtain may need to block a view. A property that suits one job can be unsuitable for another.~Which property is especially useful for a clear window?~Transparency~Being opaque~Dissolving in rain~Design a window and curtain with their different required properties.
Magnetic property choices~property~a characteristic of a material~A magnetic catch needs appropriate magnetic components. Not all metals are strongly attracted. Compare named materials, not the broad claim that metal always works.~Would aluminium automatically work like iron in a magnetic catch?~No~Yes~Only if polished~Make a material-selection table for a paper magnetic-catch design.
`);
unit(5,'Mixtures and material changes','Dissolving, melting and reacting are different processes. A mixture can often be separated using physical methods. These tasks are diagrams only: no heating, tasting, household chemical mixing or unknown-substance tests.',
 ['What should decide a separation method?','The substances and their properties','Only the mixture’s colour','Only the size of the container','Insoluble particles, dissolved substances and different boiling points need different approaches.'],`
Dissolving is not melting~solution~a mixture with a substance dissolved in a solvent~When salt dissolves in water, it spreads through the water. Melting changes a solid to its own liquid state. Dissolving and melting are not identical processes.~Is salt dissolving in water the same as melting?~No~Yes~Only if stirred~Draw separate models for dissolving salt and melting ice.
Recovering a dissolved solid~evaporation~liquid changing to gas at its surface~A dissolved solid can remain when its solvent evaporates. The solid was still present in the solution. Heating can be hazardous, so this task is a process drawing only.~What can remain when water evaporates from salt solution?~Salt~Only air~A new metal~Draw salt solution and the remaining solid after water evaporation.
Filtering an insoluble solid~filtration~separation using a filter that retains particles~A filter can separate an insoluble solid from a liquid. Dissolved salt passes with water through ordinary filter paper. Filtration alone does not make dirty water safe to drink.~Will ordinary filter paper remove dissolved salt?~No~Yes~Only if the paper is white~Draw sand retained on filter paper and liquid passing through.
Sieving by particle size~sieving~separating particles using openings of a chosen size~A sieve separates particles by size. Smaller particles pass through its openings. A sieve does not separate every mixture, particularly dissolved substances.~What property does sieving use?~Particle size~Favourite colour~Electrical charge only~Design a paper sieve diagram for two particle sizes.
Reversible physical changes~reversible~able to be changed back under suitable conditions~Melting ice and freezing water can be reversed. The substance is still water. Reversible does not mean the change reverses instantly or without suitable conditions.~Which pair can reverse a water state change?~Melting and freezing~Burning and freezing~Rusting and stirring~Draw reversible arrows between ice and liquid water.
Changes making new substances~chemical change~a change that forms new substances~Burning and rusting form new substances. They are not easily reversed like melting ice. A colour change alone is not always enough to prove a chemical reaction.~Which example forms new substances?~Rusting iron~Bending paper~Melting ice~Draw a before-and-after rusting model without testing real metals.
`);
unit(5,'Earth and the solar system','The solar system contains the Sun and objects held in orbit by gravity. Pictures help compare bodies but usually distort sizes and distances. Every drawing in these missions must say “not to scale”. Never look at the Sun.',
 ['What should a classroom solar-system drawing state?','Whether sizes and distances are to scale','That every gap shown is the real gap','That planets travel in a straight line','Most page drawings show order or relationships, not true sizes and distances together.'],`
The Sun is a star~star~a body that produces light through processes in its interior~The Sun is our nearest star. It supplies light to Earth. The Moon and planets shine mainly by reflecting sunlight, rather than being stars themselves.~Which solar-system body is a star?~The Sun~Earth~The Moon~Draw Sun, Earth and Moon with source or reflector labels and not-to-scale note.
Eight planets in order~planet~a large body orbiting a star and meeting planetary criteria~The eight solar-system planets in outward order are Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus and Neptune. Pluto is classified as a dwarf planet. Order does not show equal spacing.~Which planet lies between Earth and Jupiter?~Mars~Neptune~Mercury~Draw the eight planets in order and label the sketch not to scale.
Earth and Moon orbits~orbit~a path around another body under gravity~Earth orbits the Sun; the Moon orbits Earth. Their movements happen together. A small circle drawing simplifies their actual paths and does not show every distance.~What does the Moon orbit?~Earth~Mars~Only itself~Draw orbit relationships with arrows and a not-to-scale label.
Rotation makes day and night~rotation~turning around an axis~Earth rotates. The part facing the Sun has daylight while the far side has night. The Sun does not orbit Earth once each day to create this pattern.~What mainly causes day and night?~Earth’s rotation~The Moon switching off the Sun~Earth stopping each evening~Draw two positions on a rotating Earth with day and night labelled.
A year and a day~revolution~one complete orbit around another body~Earth takes about a year to orbit the Sun and about a day to rotate. These are different movements. A year is not one rotation of Earth.~What movement corresponds to about a year?~Earth orbiting the Sun~One rotation of Earth~The Moon making light~Draw separate rotation and orbit arrows with approximate times.
Seasons and Earth’s tilt~axis~an imagined line through a rotating body~Earth’s axis is tilted. During its orbit, different hemispheres receive sunlight differently. England’s seasons are not mainly caused by Earth moving nearer and farther from the Sun.~What mainly explains England’s seasons?~Earth’s tilted axis during its orbit~A monthly change in the Sun’s colour~England moving to another planet~Draw tilted Earth at two orbit positions and label not to scale.
`,SPACE_SOURCE);
unit(5,'Gravity, resistance and mechanisms','Forces affect motion. Gravity acts without contact; drag and friction depend on interactions with materials. Use diagram designs rather than dropping objects, climbing, launching devices or testing mechanisms near bodies.',
 ['How could a paper parachute comparison be planned?','Keep the load and release conditions the same','Change load and canopy together without records','Pick the brightest canopy','Controlling other factors helps investigate canopy design. This lesson plans the test on paper.'],`
Gravity towards Earth~gravity~an attractive interaction between masses~Earth’s gravity pulls objects towards its centre. Down points towards Earth locally, not one direction throughout space. Gravity also acts on objects that are not falling.~Where does Earth’s gravity pull nearby objects?~Towards Earth’s centre~Always towards the Moon~Only sideways~Draw Earth with arrows towards its centre from several positions.
Air resistance~air resistance~a drag force from moving through air~Air resistance opposes motion through air. A parachute can increase drag and slow descent. It does not remove gravity.~Why can a parachute slow descent?~It increases air resistance~It switches off gravity~It removes all mass~Design a paper parachute drawing and label gravity and drag arrows.
Water resistance~water resistance~drag from movement through water~Water resistance opposes relative motion through water. Streamlined shapes can reduce drag. Less drag does not mean no forces act.~What can a streamlined shape help reduce?~Water resistance~All gravity~The existence of water~Draw a streamlined swimmer model and label the direction of drag.
Friction can help~friction~a contact force that resists relative sliding~Friction helps tyres grip and brakes slow wheels. Too much friction can waste useful energy as heating. Its effect depends on the task.~Which use needs friction?~A tyre gripping a road~A planet orbiting a star~Light crossing empty space~Draw two useful friction examples with their jobs labelled.
Levers trade force and distance~lever~a bar that turns around a pivot~A lever can reduce the force needed at one end by increasing the distance moved there. It does not create energy for free. Pivot position matters.~Can a lever reduce needed force by trading distance?~Yes~No~Only by creating energy~Draw a lever with load, effort and pivot labelled.
Gears and pulleys~mechanism~connected parts used to transmit motion or force~Gears and pulleys can change how forces and motion are transmitted. A mechanism may trade force for distance or change direction. Its design does not create energy from nothing.~What can a pulley change?~The direction of an applied force~The existence of gravity~Matter into sunlight~Draw a pulley lifting a load as a paper model only.
`);

unit(6,'Classifying living things','Classification uses shared features and evidence. Groups can contain a wide variety of organisms. Microorganisms are too small to study unaided; use published illustrations, not home cultures or food left to grow mould.',
 ['How should an unknown organism be classified?','Use several relevant features and a reliable key','Choose only its colour','Assume it belongs to the first group guessed','Several features give stronger evidence. A key has a defined range and may need expert confirmation.'],`
Nested classification groups~classification~organising organisms into groups using features~A broad group can contain smaller groups. Mammals are vertebrates, and vertebrates are animals. A nested diagram shows membership, not a ranking of value.~Are mammals part of the vertebrate group?~Yes~No~Only if they live on land~Draw nested animal, vertebrate and mammal boxes.
Linnaeus and naming~species~a group of closely related organisms~Scientific names help people refer to organisms consistently. A common name can vary between places. Classification is evidence-based and can change with new information.~Why are scientific names useful?~They support consistent identification~They stop all future discoveries~They show an animal’s favourite food~Make a paper label with common and scientific names from a reliable reference.
Bacteria are organisms~bacterium~a microscopic single-celled organism~Bacteria are living cells. Some help digestion or decomposition; some cause disease. Saying every bacterium is harmful misses their different roles.~Are all bacteria harmful?~No~Yes~Only the round ones~Draw a bacterial cell model and label it not an unaided observation.
Fungi are not plants~fungus~an organism such as a mushroom, mould or yeast~Fungi obtain nutrients from other material. They do not make food by photosynthesis like green plants. A mushroom is part of a fungus, not a flower.~Is a mushroom a flower?~No~Yes~Only if it is large~Draw a fungus picture with a note explaining why it is not a plant.
Invertebrate features~arthropod~an animal with jointed legs and an outer skeleton~Insects, spiders and crabs are arthropods. Their leg counts and body sections differ. Grouping them together does not mean they are identical.~Which feature is shared by arthropods?~Jointed legs~Feathers~A backbone~Make a comparison table for an insect, spider and crab.
Plant classification clues~non-flowering~not producing flowers~Ferns and mosses are non-flowering plants. Conifers produce cones rather than flowers. Grass flowers can be small, so visible showy petals are not a reliable dividing rule.~Which plant is non-flowering?~A fern~Grass~A rose~Make a plant key using flower or non-flower reproduction clues from pictures.
`);
unit(6,'The circulatory system','The heart, blood and vessels transport substances around the body. Diagrams simplify a complex system. Use fictional examples and paper records; health advice or personal symptoms belong with a trusted grown-up and qualified professional.',
 ['How should fictional pulse results be compared?','Use the same counting duration and labelled conditions','Compare different durations as if equal','Delete values that disagree','A consistent counting method and clear conditions make comparison possible; no personal exercise test is required.'],`
The heart is a pump~heart~a muscular organ that pumps blood~The heart contracts to pump blood through vessels. It is not the place where food is digested. Its muscles need their own supply of oxygen and nutrients.~What is the heart’s main job?~Pumping blood~Digesting every food~Making all air~Draw a heart-and-vessels pump model, not a detailed anatomy claim.
Blood carries substances~blood~fluid transporting substances around the body~Blood carries oxygen, nutrients and waste products. Different blood components have different roles. Blood does not stay only inside the heart.~What does blood transport?~Oxygen and nutrients~Only sound~Only light~Draw arrows for oxygen and nutrients travelling to body cells.
Vessels form routes~blood vessel~a tube carrying blood~Arteries carry blood away from the heart; veins carry it towards the heart. These names describe direction, not whether the blood always contains much oxygen. The lung route is an important exception.~What direction defines an artery?~Away from the heart~Towards the heart~Towards the mouth only~Draw labelled away-from-heart and towards-heart vessel arrows.
Lungs and oxygen~circulation~movement of blood through the body~Blood travels to lungs to gain oxygen and release carbon dioxide. It then returns to the heart and is sent around the body. Breathing and circulation work together.~Where does blood gain oxygen?~The lungs~The teeth~The stomach lining only~Draw the simplified heart–lungs–heart–body route.
Food and water transport~absorb~take a substance across a surface into the body~Digested nutrients enter the blood from the intestine. Blood transports them to cells. Digestion and transport are different stages in supplying the body.~What happens after useful nutrients enter blood?~They can be carried to cells~They all become air~They return only to the mouth~Draw an intestine-to-blood-to-cells route with labels.
Lifestyle and the body~evidence~information used to support an explanation~Activity, diet and harmful substances can affect health. Scientific conclusions use more than one anecdote. A person’s appearance alone does not diagnose their health.~What supports a health explanation better than appearance alone?~Relevant scientific evidence~A guess about someone’s height~The colour of their clothes~Compare two fictional claims and label which would need evidence.
`);
unit(6,'Inheritance and variation','Offspring can resemble their parents while differing from them. Inherited information and environmental conditions both affect characteristics. Use invented families or plant examples; nobody needs to disclose their own family or body details.',
 ['How can inherited and environmental influences be discussed fairly?','Use evidence and recognise both can matter','Assume every difference is inherited','Assume every difference is a choice','Some characteristics involve several influences. Avoid simple claims about people from one feature.'],`
Offspring resemble parents~inheritance~passing biological information from parents to offspring~Offspring receive inherited information from parents. They are not necessarily identical copies. Resemblance is one clue, but a picture alone cannot explain every characteristic.~Must offspring be identical to a parent?~No~Yes~Only if they are plants~Draw fictional plant parents and offspring with similarities and differences.
Differences within a species~variation~differences between members of a group~Individuals of a species vary. Height, colour and other features may differ. Variation does not mean one individual has become a new species.~What is variation within a species?~Differences among individuals~Every individual being identical~An individual turning into a different species daily~Draw four imagined beetles of one species with differing patterns.
Environmental influences~environmental~arising from surroundings or experiences~Light and water conditions can affect plant growth. Such differences are not all inherited. A fair comparison needs records of the growing conditions.~Can water conditions affect plant growth?~Yes~No~Only by changing the plant’s name~Draw genetically similar imaginary plants grown in different recorded conditions.
Inherited adaptations~adaptation~a characteristic that helps survival or reproduction in a setting~An inherited feature can suit a species to its environment. A thick insulating coat helps many cold-climate animals. Adaptation does not mean an animal chooses to grow a feature because it wants one.~Does wanting a feature make it an inherited adaptation?~No~Yes~Only in winter~Draw a cold-climate animal feature and explain its possible benefit.
Plant features in dry places~survival~remaining alive in given conditions~Some desert plants store water or reduce water loss. Different species have different features. A cactus feature is useful in a context, not proof that all plants should have spines.~Why can reduced water loss help in a dry habitat?~Water is limited~There is no light~All roots disappear~Draw a dry-habitat plant and label a water-saving feature.
Similarities without simple rules~characteristic~a feature of a living thing~A characteristic can involve several inherited and environmental influences. Not every feature follows a simple either-or rule. We should not infer private family information from one appearance.~Can one visible feature explain all inheritance?~No~Yes~Only if the feature is tall~Make a paper claim-and-limit card about fictional plant height.
`);
unit(6,'Evolution and fossil evidence','Populations change across generations. Fossils and living organisms provide evidence, but the fossil record is incomplete. Evolution does not mean an individual changes species during its lifetime or that all change aims at improvement.',
 ['What strengthens an explanation of past life?','Combine relevant fossils and other evidence','Use one drawing as proof of every detail','Invent a quotation from an extinct animal','Different evidence can test parts of an explanation. Some details remain uncertain.'],`
Fossils record past life~fossil record~the known remains and traces of past organisms~Fossils show that organisms lived in the past. Many past organisms left no known fossils. An incomplete record can still give useful evidence.~Does every past organism appear in the fossil record?~No~Yes~Only every mammal~Draw a fossil evidence card with one conclusion and one limit.
Extinction~extinction~when a species has no living members remaining~Species can become extinct. Extinction is not an individual animal dying while others remain. Evidence for absence and former existence must be interpreted carefully.~What does species extinction mean?~No living members remain~One individual has died~The species has moved to another field~Draw a species timeline that ends before the present.
Variation and selection~natural selection~inherited differences affecting survival and reproduction~Inherited variation can make some individuals more likely to survive and reproduce in particular conditions. Helpful variants can become more common over generations. This is not a conscious plan.~Does natural selection require organisms to plan a change?~No~Yes~Only for plants~Draw a fictional population over generations with a clear environment label.
Change across generations~evolution~change in inherited characteristics of populations over generations~Evolution concerns populations across generations. One animal growing bigger is development, not that population’s evolution. The environment affects which characteristics are useful.~Which describes evolution?~Inherited population change over generations~One child growing taller this year~One leaf bending in wind~Compare a growth timeline with a population-change diagram.
Common ancestry~ancestor~an organism from an earlier generation~Related organisms share ancestors. A branching diagram shows relationships, not a ladder from bad to good. Living species are not all ancestors of one another.~What does a branching relationship diagram show?~Shared ancestry~A ranking of moral worth~Every species turning into humans~Draw a simple fictional branching diagram and label shared ancestor.
Darwin, Wallace and evidence~theory~an evidence-supported scientific explanation~Darwin and Wallace developed explanations involving natural selection. Scientific theories are supported explanations that can be tested and refined. Theory does not simply mean an unsupported guess.~What is a scientific theory?~An evidence-supported explanation~Any unsupported guess~An opinion that cannot be questioned~Make a paper evidence-and-explanation card for natural selection.
`);
unit(6,'Light paths and vision','Light paths can be represented with straight arrows in simple ray models. Objects are seen when light reaches eyes. Models help explain shadows and reflection while leaving out details such as scale.',
 ['What makes a useful light-ray diagram?','Arrow directions and labelled objects','Arrows pointing every way without labels','A claim that eyes send seeing rays','Ray arrows show a proposed route. A diagram needs the source, object and eye or screen identified.'],`
Straight-line ray models~ray~an arrow representing a light path~In a uniform material, light is modelled as travelling in straight lines. A ray is a diagram tool, not a thin solid stick. It helps reason about where light can reach.~What does a ray arrow represent?~A light path~A solid rod~The path of an eye~Draw a source and three straight light-ray arrows.
Reflection into an eye~reflection~light changing direction at a surface~Light from a source can reflect off an object into an eye. The eye receives light. An ordinary book need not produce its own light to be seen.~How is a book usually seen?~Reflected light enters the eye~The eye shoots rays out~The book must be a star~Draw a lamp–book–eye route with arrowheads.
Mirror directions~normal~an imagined line perpendicular to a surface~A simple mirror ray model uses a normal line. Incoming and outgoing rays have equal angles to it. The normal is a reference, not another light ray.~What is the normal line used for?~Measuring angles to the surface~Supplying light~Absorbing every ray~Draw a mirror, normal and equal-angle reflection model.
Shadows and object outlines~shadow~an area reached by less light because light is blocked~An opaque object blocks paths from a source. Shadow outlines depend on source, object and screen positions. A shadow is not a material leaving the object.~What explains a shadow?~Blocked light paths~Dark material leaking out~The screen becoming a new substance~Draw rays past the edges of an opaque shape to a screen.
Changing shadow geometry~geometry~relationships of shapes, distances and angles~Changing distances can change a shadow’s size. Keep source and screen fixed while comparing object positions. Drawings predict a pattern but should not be mistaken for measurements.~What is needed to test a shadow-size prediction?~Actual labelled observations or measurements~Only a confident guess~Only a colourful drawing~Make a two-position paper prediction with changed distance marked.
Refraction as extension~refraction~light changing direction when its speed changes between materials~Light can change direction when entering a different material. A pencil can appear bent at a water surface. The pencil need not actually bend; refraction changes the light path.~Why can a pencil appear bent in water?~Light changes direction~Water always breaks the pencil~The eye moves the pencil~Draw a labelled water-surface ray model; no glass handling is needed.
`);
unit(6,'Circuit symbols and comparisons','Symbols make circuits easier to compare. A cell supplies energy, and current flows through a complete conducting path. Use diagrams and provided examples only; no mains, exposed wiring or battery experiments are required.',
 ['What must be included in a circuit brightness comparison?','Supply and connections as well as observations','Only component colour','Only the person who drew it','Brightness depends on the circuit and components. A fair claim describes the setup.'],`
Standard circuit symbols~symbol~a conventional mark representing a component~Standard symbols stand for cells, switches, bulbs and other components. They show connections rather than physical appearance. A neat picture is not automatically a working circuit.~What does a circuit symbol represent?~A component~Its exact physical size~Its owner’s age~Make a paper legend for cell, bulb and switch symbols from a reference.
Voltage and the supply~voltage~a measure of energy transferred per unit charge~A suitable supply provides a voltage across a circuit. Increasing the supply can change bulb brightness within safe ratings. More voltage is not always safe or better.~Does increasing voltage always improve a device safely?~No~Yes~Only if wires are colourful~Draw two paper circuit examples with clearly labelled supplies.
Current in a series path~current~the rate of flow of electric charge~In a single series path, current is the same at different points. A bulb transfers energy; it does not use up the charge. A gap stops the current.~Does a bulb use up electric charge?~No~Yes~Only a large bulb does~Draw a series loop and mark equal current at three points.
Adding series components~series~connected along a single path~Adding bulbs in series can reduce current with the same supply and change brightness. The effect depends on the components. A claim should describe the circuit, not just say more bulbs is better.~What defines series components?~One shared path~Separate independent branches~Different colours~Draw one-bulb and two-bulb series layouts with the same supply.
Buzzer and motor functions~component~a part of a circuit with a particular role~A buzzer can produce sound, and a motor can produce movement. Energy is transferred into different forms. A component’s function does not replace the need for a complete path.~Which component can produce movement?~A motor~An open switch~A broken wire~Design a paper device using a motor and label its useful output.
Diagnosing with evidence~diagnose~identify a cause using evidence~A circuit may fail because of several possible faults. Change or check one thing at a time in a supervised investigation. A paper diagram can reveal a gap but not every hidden component fault.~Can a diagram prove every real component works?~No~Yes~Only if drawn in blue~Mark visible and potentially hidden faults on an imagined circuit plan.
`);

unit(7,'Cells and organisation','Cells are basic units of living organisms. Microscopy and biological models provide evidence at different scales. Drawings here are illustrative and not to scale; a model is not an unaided view of a real cell.',
 ['How should two microscope images be compared?','Check scale or magnification as well as features','Assume the bigger printed image has bigger cells','Ignore every scale bar','Printed image size is not cell size. A scale bar or magnification provides essential context.'],`
Animal-cell structures~cell membrane~the boundary controlling movement into and out of a cell~A typical animal-cell model includes membrane, cytoplasm, nucleus and mitochondria. Cytoplasm is where many chemical reactions happen. Mitochondria carry out many stages of aerobic respiration, transferring energy from food for cell activities; energy is not created from nothing. Aerobic means using oxygen. Real cells differ in shape and function. A circular school drawing is not the shape of every animal cell.~What is a cell membrane’s role?~Controlling entry and exit~Making a rigid plant wall~Being the entire organism’s skeleton~Draw an animal-cell model labelled illustrative and not to scale. Label membrane, cytoplasm, nucleus and mitochondria, with a function for each.
Plant-cell structures~cell wall~a supporting boundary outside a plant cell membrane~Plant cells have a cell wall outside the membrane. A typical mature plant cell has a large vacuole containing cell sap, a watery solution. Water in the vacuole presses the contents against the wall, helping keep the cell firm; this support is called turgor. Plant cells also have mitochondria and carry out respiration. Many photosynthetic plant cells have chloroplasts. Not every plant cell has chloroplasts, such as many root cells.~Do all plant cells contain chloroplasts?~No~Yes~Only every root cell does~Compare a leaf-cell and root-cell model with differences labelled. Include a vacuole with cell sap, the cell wall and mitochondria. Explain how the filled vacuole helps support the cell.
Nucleus and genetic information~nucleus~a cell structure containing genetic material in many organisms~The nucleus contains genetic material in typical plant and animal cells. It helps coordinate cell activities. Bacteria do not have a nucleus of this kind.~Which structure contains genetic material in a typical animal cell?~Nucleus~Cell wall~Chloroplast~Draw nucleus, cytoplasm and membrane with role labels.
Specialised cells~specialisation~features suited to a particular function~A root-hair cell has a projection that increases surface area for absorption. Different cell structures suit different jobs. Specialised cells are still cells, not miniature complete organs.~How does a root-hair projection help?~It increases absorption surface area~It makes light underground~It turns the root into an animal~Draw a root-hair cell and explain the surface-area benefit.
Cells to organ systems~tissue~a group of cells working together~Cells form tissues; tissues form organs; organs cooperate in systems. Each level involves organisation. A heart is an organ, not a single cell.~Which sequence increases in level of organisation?~Cell → tissue → organ~Organ → cell → tissue~Tissue → organ → cell~Make a nested organisation diagram using a fictional body example.
Microscopes and scale~magnification~how many times larger an image appears than its object~Magnification compares image size with actual size using matching units. An image 20 mm wide of an object 2 mm wide has magnification ×10. A model drawing needs a different kind of label.~What is 20 mm divided by 2 mm as magnification?~×10~×40~×2~Draw a scale-labelled image example and calculate its magnification.
`);
unit(7,'Body systems and exchanges','Organs have structures suited to their functions. Digestion, ventilation, gas exchange and circulation cooperate, but they are different processes. Clinical diagrams are simplified; these activities require no body measurements or dissection.',
 ['What makes a body-process explanation stronger?','Connect a named structure to its function','List organ names without relationships','Assume every organ performs every job','Structure-and-function reasoning explains why a feature matters, not merely where it is.'],`
Enzymes and digestion~enzyme~a biological catalyst that speeds a reaction~Digestive enzymes help break large food molecules into smaller ones. Different enzymes act on different substances. Chewing is mechanical breakdown, not the same as an enzyme reaction.~What does a digestive enzyme do?~Speeds breakdown reactions~Becomes a tooth~Carries air into the lungs~Draw mechanical chewing and chemical digestion as separate processes.
Small-intestine surface area~villus~a small projection increasing intestinal surface area~Villi increase the small intestine’s surface area for absorption. Digested substances cross into the body. A large surface area helps transfer without making each molecule larger.~Why are villi useful?~They increase absorption surface area~They stop all absorption~They make food molecules larger~Draw a flat and folded surface model and compare their exposed areas.
Ventilation and breathing~ventilation~movement of air into and out of lungs~The diaphragm and rib muscles help change chest volume. Pressure changes move air. Ventilation is not the same as cellular respiration, which involves chemical reactions.~What is ventilation?~Moving air into and out of lungs~Making glucose in leaves~All chemical reactions in cells~Draw a labelled inhalation model without breath-holding or exercise tests.
Gas exchange in alveoli~alveolus~a tiny air sac involved in gas exchange~Alveoli provide a large area with thin exchange surfaces. Oxygen moves into blood and carbon dioxide out. Gas exchange is movement of gases, not creation of oxygen.~Why are thin exchange surfaces useful?~They shorten diffusion distance~They prevent any gas movement~They make oxygen from nothing~Draw an alveolus and capillary with gas-direction arrows.
Muscles, bones and joints~joint~a place where bones meet~Muscles pull on bones across joints. Antagonistic pairs can move a joint in opposite directions. A contracting muscle pulls rather than pushing the bone back.~How do antagonistic muscles help movement?~They pull in opposing actions~They both turn into bone~They eliminate every force~Draw an elbow lever model with muscle pulls marked.
Nutrition and evidence~balanced diet~a suitable range and amount of nutrients~Nutrients support energy needs, growth and repair. Requirements vary with circumstances. Dietary science uses evidence; this course does not prescribe an individual’s diet or diagnose deficiencies.~What should guide a scientific nutrition claim?~Relevant evidence about nutrients and needs~An influencer’s appearance alone~The price of the plate alone~Compare two fictional food claims and state what evidence is missing.
`);
unit(7,'Particles and physical properties','Particle models explain states and changes. Dots are symbols, not photographs, and drawings are not to scale. The particles of a substance do not simply expand into larger particles when that substance is heated.',
 ['What should a particle-model diagram explain?','What dots, spaces and arrows represent','That dots have the real drawn size','That every particle is a coloured ball','A key distinguishes the model from reality and links arrangement or motion to a property.'],`
Solid particle arrangements~particle~a small constituent represented in a material model~In a simple solid model, particles are close and vibrate around fixed positions. They are not completely motionless. The model helps explain a solid’s fixed shape.~Are particles in a solid completely motionless?~No~Yes~Only if the solid is metal~Draw a solid particle model with vibration arrows and not-to-scale label.
Liquid particle motion~fluid~a substance that can flow~In a liquid model, particles remain close but can move past one another. A liquid has a fixed volume but takes container shape. The particles do not become tiny drops of liquid themselves.~Why can a liquid change shape?~Particles can move past one another~Its particles disappear~Every particle melts again~Draw two container shapes with the same number of model particles.
Gas particles and space~compress~reduce volume by applying pressure~Gas particles are widely separated in a simple model. Gases can be compressed much more readily than liquids. Much of the change reduces spaces, not the size of each particle.~What mainly reduces when a gas is compressed?~Spaces between particles~Each particle’s identity~The number of atoms necessarily~Draw before-and-after gas models with equal particle counts.
Diffusion~diffusion~net movement from higher to lower concentration through random motion~Random particle motion can spread a substance. Net movement is from higher to lower concentration. The particles do not all choose one direction consciously.~What causes diffusion in a particle model?~Random particle motion~Particles making a plan~All particles standing still~Draw a concentration difference before and after spreading.
Density calculations~density~mass per unit volume~Density equals mass divided by volume. A 20 g sample occupying 10 cm³ has density 2 g/cm³. A bigger object need not be made of a denser material. Upthrust is an upward force from a fluid, such as water or air. In water, pressure is greater at the bottom of an object than at its top, producing upthrust. For an object floating freely at rest, with no other vertical forces, upthrust balances its downward weight.~What is the density of 20 g in 10 cm³?~2 g/cm³~200 g/cm³~0.5 g/cm³~Make a labelled mass-volume calculation card for this example. Beside it draw a floating object at rest: equal-length arrows show weight down and upthrust up. State that the arrow lengths compare forces, not distances.
Gas pressure and collisions~pressure~force per unit area~Gas particles collide with surfaces and exert pressure. Heating a fixed amount of gas at fixed volume can increase pressure. The condition of fixed volume matters. Liquid pressure increases with depth in the same still liquid: there is more liquid weight above a deeper point. In an imagined water tank, a point 8 cm below the surface has greater pressure than a point 2 cm below it. Atmospheric pressure is the pressure of the surrounding air. It generally decreases with height because there is less weight of air above you.~What produces gas pressure on a container wall?~Particle collisions~Wall colour~Particles choosing to be heavy~Draw gas collision arrows in a closed-container model. Add an imagined water tank with points at depths 2 cm and 8 cm. Label which has greater pressure. Draw an air-column model explaining why atmospheric pressure generally falls with height.
`);
unit(7,'Pure substances and separation','Mixtures contain substances together without all being chemically bonded into one substance. Separation depends on properties. Plan methods on paper; laboratory heating, solvents and apparatus require trained supervision.',
 ['Why choose a separation method by properties?','Different mixtures need different methods','Every mixture can use the same sieve','Colour alone always identifies purity','Solubility, particle size and boiling behaviour help choose an appropriate method.'],`
Pure in chemistry~pure substance~one chemical substance rather than a mixture~In chemistry, pure has a specific meaning. Pure water contains only water, while mineral water contains dissolved substances. A marketing word is not an analytical test.~Is mineral water chemically pure water?~No~Yes~Only if the bottle is clear~Compare a pure-water particle model with a mineral-water mixture model.
Mixtures and dissolved substances~solute~a substance dissolved in a solvent~Salt is the solute in saltwater; water is the solvent. Dissolving forms a mixture, not necessarily a new compound. The dissolved particles remain present.~What is the solute in saltwater?~Salt~The container~The filter paper~Draw a solution key identifying solute and solvent.
Filtrate and residue~residue~solid retained during filtration~Filtration can retain an insoluble solid as residue. Liquid passing through is filtrate. Dissolved substances can pass too, so clear filtrate is not proof of safe drinking water.~What is the liquid passing through a filter called?~Filtrate~Residue~A catalyst~Draw and label filter, residue and filtrate in a paper plan.
Crystallisation~crystallisation~formation of solid crystals from a solution or melt~A solution can produce crystals when conditions change. Crystallisation can recover a dissolved solid. This task is a model; no heating or growing unknown crystals is needed.~What can crystallisation recover from a solution?~A dissolved solid~Only light~Only an insoluble pebble~Draw a solution and later crystals, with stages labelled as a model.
Distillation~distillation~separation involving evaporation and condensation~Distillation vaporises a liquid and condenses it for collection. It can separate water from dissolved salt. Evaporation alone does not collect the liquid afterwards.~What extra step collects liquid in distillation?~Condensation~Sieving~Painting the flask~Draw a distillation process map without assembling apparatus.
Chromatography~chromatography~separation by different movement through a system~Components move differently in chromatography because of their interactions with the stationary and moving phases. Several separated spots can indicate several detected components. One spot does not prove purity: components may overlap or go undetected. In our fictional data, ink A has two detected spots and ink B has one.~What can several separated spots suggest about an ink?~It contains several components~It must be one pure substance~Its container changed colour~Use fictional example data, not a real experiment: ink A has spots 2 cm and 5 cm above the starting line; ink B has one spot 5 cm above it. Draw two labelled lanes with those spots. Label the number of detected spots and explain why B’s one spot does not prove purity.
`);
unit(7,'Forces and motion','Forces can change motion or shape. Diagrams show vectors with direction and magnitude. Numerical examples specify units and assumptions; the missions use paper calculations, not launches, drops or heavy loads.',
 ['How can a motion calculation be checked?','Use the given quantities with consistent units','Add every number without checking meaning','Ignore time units','The quantity relationship and units determine the calculation, not just the numbers available.'],`
Resultant forces~resultant~the combined effect of forces~Opposing forces of 8 N right and 3 N left give a resultant 5 N right. Direction matters. Adding magnitudes without directions gives the wrong resultant here.~What is 8 N right combined with 3 N left?~5 N right~11 N right~5 N left~Draw the two force arrows and calculate the resultant.
Balanced motion~balanced forces~forces whose resultant is zero~With zero resultant force, an object can remain still or move at constant velocity. Balanced does not necessarily mean stationary. Changing velocity requires a resultant force.~Can an object move with balanced forces?~Yes; at constant velocity~No; it must stop~Only if there is no mass~Draw a stationary and a constant-velocity example with zero resultant.
Speed as distance over time~speed~distance travelled per unit time~Average speed equals total distance divided by total time. Travelling 30 m in 10 s gives 3 m/s. Speed does not state a direction.~What is the average speed for 30 m in 10 s?~3 m/s~300 m/s~20 m/s~Write the relationship and substitute the units in a calculation card.
Distance-time graph slopes~gradient~the steepness of a graph~On a distance-time graph, a steeper slope indicates greater speed. A horizontal section indicates no increase in distance. Axis scales must be checked before comparing slopes on different graphs.~What does a horizontal distance-time section show?~Distance is not increasing~Speed is increasing continuously~Distance doubles every second~Draw a fictional stop-and-travel graph with labelled axes.
Mass and weight~weight~the gravitational force on an object~Mass is measured in kilograms; weight is a force measured in newtons. Near Earth, weight is approximately mass multiplied by gravitational field strength. Mass does not vanish on the Moon.~Is weight measured in kilograms or newtons?~Newtons~Kilograms~Seconds~Make a mass-versus-weight table with quantities and units.
Moments about a pivot~moment~the turning effect of a force~A moment equals force times perpendicular distance from a pivot. A 4 N force 0.5 m away gives 2 N m. Distance along an angled line is not automatically the perpendicular distance.~What is 4 N multiplied by 0.5 m?~2 N m~8 N m~4.5 N m~Draw a lever with the perpendicular distance and moment calculation.
`);
unit(7,'Energy and useful transfers','Energy can be stored and transferred. It is conserved, though useful energy can become spread into less useful stores. A device does not use up energy by destroying it; consider the whole system.',
 ['What should an energy account include?','Useful transfers and energy reaching surroundings','Only the useful output','A claim that unwanted energy disappears','A complete account considers the surroundings. Less useful does not mean no energy remains.'],`
Energy stores~energy store~a way energy is held in a system~A moving object has a kinetic energy store. A stretched spring has an elastic store. These categories help describe a system; energy is not a physical coloured substance.~Which store is associated with motion?~Kinetic~Elastic only~Chemical only~Draw three fictional systems and label their energy stores.
Energy transfer pathways~transfer~movement of energy between stores or systems~Energy can be transferred electrically, mechanically, by heating or by radiation. A pathway differs from a store. Light is a transfer by radiation, not a container full of energy.~Which is an energy-transfer pathway?~Electrical transfer~The name of a battery~Object colour alone~Draw a battery-powered motor energy account with pathway labels.
Work done~work~energy transferred by a force acting through a distance~Work done equals force times distance in the force direction. A 5 N force acting through 2 m transfers 10 J. Units and direction are part of the model.~What is 5 N acting through 2 m?~10 J~2.5 J~7 J~Write a labelled work calculation for the given example.
Power and time~power~energy transferred per unit time~Power equals energy transferred divided by time. Transferring 60 J in 3 s gives 20 W. Greater power does not necessarily mean greater total energy if the time differs.~What is 60 J transferred in 3 s?~20 W~180 W~63 W~Compare two fictional equal-energy transfers with different times.
Conservation of energy~conserved~not created or destroyed in the total account~Energy is conserved in transfers. Friction can transfer energy into thermal stores of surroundings. That energy is harder to use for the original purpose, but it has not disappeared.~What happens to energy spread by friction?~It remains in other stores~It is destroyed~It becomes negative matter~Draw a slowing object’s energy account including surroundings.
Energy resources~renewable~replenished by natural processes on useful human timescales~Wind and sunlight are renewable energy resources. Fossil fuels are not replenished rapidly on human timescales. Every technology has practical and environmental considerations.~Which resource is renewable?~Wind~Coal~Crude oil~Make a resource comparison table with one benefit and one limitation each.
`);

unit(8,'Photosynthesis and respiration','Organisms transfer energy through chemical processes. Photosynthesis and respiration are different processes, not simple opposites happening in separate kingdoms. Green plants respire as well as photosynthesise.',
 ['How can a claim that plants only respire at night be checked?','Compare evidence about plant cells in light and darkness','Assume plants never need energy in daylight','Decide from leaf colour alone','Plant cells need respiration day and night. Light availability affects photosynthesis, not the existence of respiration.'],`
Photosynthesis inputs~photosynthesis~using light energy to make sugars from carbon dioxide and water~Photosynthesis uses carbon dioxide and water to make glucose and oxygen in a simple word equation. Light energy is required. The plant does not obtain all its food ready-made from soil.~Which gas is an input to photosynthesis?~Carbon dioxide~Oxygen~Helium~Draw a photosynthesis input-output map with light energy labelled.
Chloroplasts and chlorophyll~chlorophyll~a pigment absorbing light for photosynthesis~Chlorophyll in chloroplasts absorbs light. Many green plant cells have chloroplasts. Root cells often do not, so plant cell is not identical to photosynthesising cell.~What is chlorophyll’s role?~Absorbing light~Pumping blood~Making mineral atoms disappear~Draw a labelled leaf-cell model and mark it not to scale.
Leaves and gas exchange~stoma~a pore involved in gas exchange in leaves~Stomata allow gases to move between leaves and air. They also affect water loss. Gas exchange depends on conditions; a leaf is not a sealed bag.~What can move through stomata?~Gases~Whole root systems~Large stones~Draw a magnified stoma model with gas and water-vapour arrows.
Aerobic respiration equation~aerobic respiration~reactions releasing energy from glucose using oxygen~A simple word equation is glucose plus oxygen producing carbon dioxide and water. Energy is transferred for cell processes. Respiration is not merely breathing air in and out.~Which gas is used in aerobic respiration?~Oxygen~Helium~Nitrogen only~Draw the respiration word equation and label the energy transfer.
Plants respire too~cellular~happening in cells~Plant cells respire during day and night. Photosynthesis needs light and can supply glucose. The balance of gas exchange depends on rates, not the rule plants never respire in daylight.~Do plants respire in daylight?~Yes~No~Only if they have no leaves~Make a day/night process table for photosynthesis and respiration.
Anaerobic respiration~anaerobic~without oxygen~Cells can release some energy without oxygen. In human muscle this can produce lactate; yeast fermentation produces ethanol and carbon dioxide. Different organisms do not always have identical products.~What gas can yeast fermentation produce?~Carbon dioxide~Helium~Chlorine~Compare muscle and yeast anaerobic processes in a paper table.
`);
unit(8,'Ecosystems and interdependence','Ecosystems include organisms and their physical environment. Feeding relationships, competition and decomposition connect them. A food-web diagram simplifies a complex system; it does not predict every consequence with certainty.',
 ['How should a food-web prediction be stated?','Use the connections and state uncertainty','Assume one change affects nothing else','Claim every population changes by exactly ten','Connections support a reasoned prediction, but other factors and missing data limit precision.'],`
Producers and consumers~producer~an organism making organic food from simple substances~Green plants are producers in many food webs. Consumers obtain food from other organisms. A producer is not defined by being large or located at the top of a picture.~Which organism is a producer?~Grass~A rabbit~A fox~Draw grass, rabbit and fox with producer and consumer labels.
Food webs and arrows~food web~a network of feeding relationships~Food-web arrows usually point from food towards the eater, showing transfer. An organism can have several food sources or predators. A web is more interconnected than one chain.~Which way does a feeding arrow point?~From food to eater~Always from larger to smaller~Always left to right~Draw a fictional web with at least two feeding paths.
Competition for resources~competition~organisms using the same limited resources~Plants may compete for light, water and mineral nutrients. Animals may compete for food or space. Competition need not involve fighting or conscious planning.~Can plants compete without fighting?~Yes~No~Only if they walk~Draw two imagined plants shading one another and label the shared resource.
Decomposers recycle matter~decomposer~an organism breaking down dead organic material~Fungi and bacteria help break down dead material. Matter can return to the environment for reuse. Energy is transferred and spread, not endlessly recycled as matter is.~What do decomposers help recycle?~Matter and nutrients~Unlimited useful energy~Only sunlight~Draw dead leaf → decomposers → soil nutrients → plant as a matter model.
Biodiversity~biodiversity~the variety of living organisms in a setting~An ecosystem can contain many species and interactions. Biodiversity is more than counting one favourite species. Surveys should consider method and the area studied.~What describes biodiversity?~Variety of living organisms~Only the tallest tree~Only the number of foxes~Design a fictional habitat survey recording several groups.
Sampling fairly~sample~a selected part used to investigate a larger set~A sample gives evidence about a larger area but may be unrepresentative. Choosing only the richest patch can bias a survey. A planned sampling method improves comparisons.~Which sampling choice is biased?~Choosing only patches with most flowers~Using a planned range of patches~Recording the surveyed area~Mark planned survey squares on a paper habitat map.
`);
unit(8,'Atoms, elements and compounds','Atoms are too small for these drawings to show literally. Particle and electron-shell pictures are scientific models, labelled not to scale. Colours stand for types; electrons are not tiny planets moving on drawn circular tracks.',
 ['What is a limitation of an electron-shell drawing?','It does not show literal electron paths or true scale','Every circle is a real railway-like track','Its colours are the atoms’ actual colours','The model organises electrons into energy levels; it is not a photograph or a literal planetary system.'],`
Nucleus and electrons~atom~a small unit of an element~An atom has a tiny nucleus and electrons associated with it. Protons are positively charged; electrons are negatively charged. Most atomic mass is in the nucleus, not spread evenly through the drawing.~Where is most atomic mass concentrated?~The nucleus~The outer drawn circle~Empty space equally~Draw an illustrative atom model labelled not to scale.
Electron energy levels~electron shell~a simplified way to organise electron energy levels~Shell diagrams help organise electron arrangements. They do not show literal paths like planetary orbits. More advanced models describe probabilities of finding electrons rather than fixed circular tracks.~Are drawn electron shells literal circular tracks?~No~Yes~Only if drawn in blue~Compare a shell sketch with a note about its nonliteral nature.
Elements and proton number~element~a substance defined by one kind of atom~An element is defined by the proton number of its atoms. Carbon atoms have six protons. Changing neutron number makes an isotope, not a different element. Chemical symbols name elements: H is hydrogen, O is oxygen and C is carbon. The capital letter matters; a symbol is not a drawing of the atom.~What defines an element’s identity?~Proton number~Container shape~The colour used in a diagram~Draw two carbon isotope models with equal protons and different neutrons. Add a symbol key: H hydrogen, O oxygen, C carbon.
The periodic table~periodic table~an arrangement of elements by atomic number and recurring properties~Elements are ordered by atomic number. Columns called groups can share chemical patterns. The table is not an alphabetical list or a ranking of importance.~How are elements ordered in the periodic table?~By atomic number~Alphabetically only~By how useful they seem~Mark rows and columns on a simplified paper table.
Molecules and compounds~compound~a substance with different elements chemically combined~Water contains hydrogen and oxygen chemically combined. Its formula H2O represents two hydrogen atoms and one oxygen atom per molecule. The small formula number, called a subscript, counts atoms of the element just before it; no subscript means one. Carbon dioxide, CO2, has one carbon atom and two oxygen atoms per molecule. Oxygen, O2, has two oxygen atoms per molecule, but only one element, so it is not a compound. In 2H2O, the large number before the formula counts two whole water molecules: four hydrogen atoms and two oxygen atoms in total. Some compounds form giant structures rather than separate molecules.~Is an oxygen molecule a compound?~No~Yes~Only if there are two atoms~Draw O2, H2O and CO2 particle models with an atom-type key. Then draw two separate H2O molecules and count all hydrogen and oxygen atoms. Label drawings illustrative and not to scale; changing a front number changes the molecule count, not the formula of each molecule.
Mixtures keep constituents~mixture~substances together without being one chemically bonded substance~Air is a mixture of gases. Its constituents are not all bonded into a single new compound. Mixture proportions can vary, unlike a compound’s defined composition.~Is air one compound?~No; it is a mixture~Yes; it is one element~Yes; every gas is bonded together~Draw a mixed-gas particle model with more than one labelled type.
`,ATOM_SOURCE);
unit(8,'Chemical changes and reactions','A chemical reaction rearranges atoms into different substances. Evidence needs interpretation, and equations account for reactants and products. All missions are paper reasoning; do not mix chemicals, use flames or handle laboratory acids.',
 ['What is stronger evidence for a reaction than colour alone?','Evidence that new substances form','The container being attractive','A claim that every colour change is a reaction','Colour can change for several reasons. Identifying products strengthens a reaction explanation.'],`
Reactants and products~reactant~a starting substance in a reaction~Reactants are converted to products through chemical change. Atoms are rearranged, not normally created or destroyed in an ordinary chemical reaction. A word equation names substances on each side.~Which side of a word equation names starting substances?~Reactants~Products~Only the arrow~Draw a word-equation template with reactants and products labelled.
Conservation of mass~closed system~a system with no matter entering or leaving~In a closed system, ordinary chemical reactions conserve total mass. Gas escaping can change a measured mass in an open container. Missing gas is not proof that atoms disappeared.~Why can mass fall in an open gas-producing reaction?~Gas leaves the measured system~Atoms are destroyed~The balance makes matter vanish~Draw closed and open reaction-system boundaries and label matter flow.
Acids, alkalis and indicators~indicator~a substance whose response helps identify chemical conditions~Indicators can show acidity or alkalinity through colour. pH describes acidity, with neutral aqueous solutions near pH 7 under usual school conditions. Colour names depend on the indicator used.~What must be named when interpreting an indicator colour?~The indicator~Only the beaker’s owner~Only the room’s colour~Make a reference-based indicator chart without testing household liquids.
Neutralisation~neutralisation~a reaction between an acid and a base~Acids react with bases; suitable acid–alkali reactions form salt and water. Not every resulting salt solution must have pH exactly 7. The substances and amounts matter.~What can an acid–alkali neutralisation form?~Salt and water~Only helium~Only solid wood~Draw an acid + alkali → salt + water word-model card.
Energy in reactions~exothermic~transferring energy to surroundings~Exothermic reactions transfer energy to surroundings; endothermic changes take energy from surroundings. Temperature evidence depends on the setup. Hot is an observation, not a complete chemical identity.~Which term means energy is transferred to surroundings?~Exothermic~Endothermic~Transparent~Draw energy-direction arrows for both kinds of change.
Oxidation and decomposition~oxidation~a reaction involving oxygen in an introductory model~A metal reacting with oxygen forms an oxide. Thermal decomposition breaks a compound down through heating. These are different reaction patterns; neither needs home testing here.~What can form when a metal reacts with oxygen?~A metal oxide~Only a pure gas of the metal~A wooden compound~Write a generic metal + oxygen → metal oxide card.
`);
unit(8,'Waves, sound and light','Waves can transfer energy without transporting all the material along with them. Models show selected features. Read axis scales carefully and avoid loud sound, lasers or looking at bright sources.',
 ['What is needed to compare two wave diagrams?','Check their time and displacement scales','Compare colour only','Assume every drawn wave is the same scale','Amplitude and frequency cannot be compared reliably if diagram scales are unknown.'],`
Sound needs a medium~longitudinal~a wave with oscillations parallel to its travel direction~Sound in air is longitudinal, with compressions and rarefactions. It needs a material medium. Sound does not travel through an ideal vacuum, though light can.~Can ordinary sound travel through an ideal vacuum?~No~Yes~Only high-pitch sound can~Draw air compressions as a model with travel direction labelled.
Frequency and period~frequency~the number of complete oscillations each second~Frequency is measured in hertz. A 5 Hz source completes five oscillations per second. Period is time for one oscillation, not the height of the wave.~What does 5 Hz mean?~Five oscillations each second~Five metres of amplitude~Five seconds for every oscillation~Draw five example cycles across one second and label the time axis.
Amplitude versus pitch~amplitude~maximum displacement from the rest position~Larger amplitude usually means louder sound, while frequency affects pitch. A louder sound need not be higher-pitched. The two features can vary independently.~Which feature mainly affects sound pitch?~Frequency~Amplitude alone~Wave colour~Draw two same-frequency models with different amplitudes.
Reflection angles~angle of incidence~the angle between an incoming ray and the normal~For a plane mirror, incidence and reflection angles are equal, measured from the normal. Angles measured from the surface are different. A labelled normal avoids confusion.~From what line is incidence angle measured?~The normal~The mirror edge direction~The page border~Draw a 30° incidence example with a 30° reflection angle.
Refraction and lenses~lens~a shaped transparent object that refracts light~Refraction changes light direction at a boundary when speed changes. Lenses use this to alter ray paths. A simple ray diagram leaves out wavelength effects and practical imperfections.~What does a lens mainly use to redirect light?~Refraction~Sound absorption~Magnetic attraction~Draw a simple converging-lens ray model labelled illustrative.
White light and colour~spectrum~a range of wavelengths or colours~White light contains a range of visible wavelengths. A prism can separate colours through different refraction. A red surface usually reflects red light more than other visible colours, rather than making red light itself.~What can a prism separate from white light?~A spectrum of colours~Different kinds of sound~Only black particles~Draw a prism spectrum model and label it not to scale.
`);
unit(8,'Current, resistance and magnetism','Electric and magnetic models describe related but different interactions. Current is charge flow, while voltage concerns energy per charge. Use paper diagrams and calculations only, with no mains, coils or battery experiments.',
 ['How should an electrical comparison be made?','State the circuit, supply and measured quantities','Judge current from wire colour','Ignore whether components are in series','Circuit structure matters. A diagram and units make a claim testable and interpretable.'],`
Current and charge conservation~ampere~the unit of electric current~Current measures charge flow per time. In a series path it is equal at different points. Charge is not consumed by a lamp; energy is transferred there. Static electricity is an imbalance of electric charge. When electrons transfer between two initially neutral objects, the one gaining electrons becomes negative and the one losing them becomes positive. Total charge is conserved, not created. In an imagined transfer, object A gains three electrons from B; A is negative and B is positive by equal amounts. Like charges repel and unlike charges attract. These non-contact forces act through an electric field, a region where a charge experiences an electric force.~Is current used up along a series circuit?~No~Yes~Only by the first lamp~Draw equal-current markers around a complete paper series circuit. Beside it draw two initially neutral objects and arrows for three electrons moving from B to A. Label final charges and count electrons before and after; this is an imagined paper model, not an instruction to build a circuit or charge objects.
Parallel branches~parallel~connected on separate paths between the same two points~A parallel circuit has branches. Current can divide between branches and recombine. A broken branch need not break every other branch, provided their paths stay complete.~What can current do at parallel branches?~Divide and later recombine~Disappear permanently~Become only light~Draw a two-branch circuit and label a junction.
Potential difference~potential difference~energy transferred per unit charge between points~Voltage is potential difference, measured in volts. A volt corresponds to a joule per coulomb. It is not another name for current.~Is voltage the same quantity as current?~No~Yes~Only in a red wire~Make a units card separating volts, amperes and joules.
Resistance calculations~resistance~a measure relating potential difference to current~For a stated operating condition, resistance is voltage divided by current. At 6 V and 2 A, resistance is 3 Ω. Not every component keeps constant resistance as conditions change.~What is 6 V divided by 2 A?~3 Ω~12 Ω~8 Ω~Show the relationship and units for the given resistance example.
Magnetic fields~magnetic field~a region described by magnetic effects and direction~A field model represents magnetic influence around a magnet. Field lines are diagram tools, not strings in space. Earth’s magnetic field helps orient a compass.~Are magnetic field lines physical strings?~No~Yes~Only near Earth~Draw a bar-magnet field model with a clear model label.
Electromagnets~electromagnet~a magnet produced using electric current~Current through a coil can produce a magnetic field. An iron core can strengthen a suitable electromagnet. It can be controlled electrically, unlike assuming every magnet requires a battery.~What produces an electromagnet’s field?~Electric current~Paint colour~The sound of a switch~Design a paper electromagnet device with control and field labels.
`);

unit(9,'Human reproduction and development','These are clinical biology explanations, with respectful scientific terms. People’s bodies and experiences vary. Use labelled textbook-style diagrams; nobody needs to share personal information. A trusted grown-up can help with private questions.',
 ['How should a reproductive-system diagram be used?','Identify structures and functions without judging people','Infer somebody’s private life from appearance','Treat a model as every person’s exact anatomy','A simplified model teaches structures. It does not justify assumptions about an individual’s body, identity or experiences.'],`
Reproductive organs and functions~ovary~an organ containing egg cells and producing hormones~Ovaries contain egg cells; testes produce sperm. The uterus can support a developing pregnancy. These structures have different functions, and a diagram is a simplified anatomical model.~Where are sperm produced?~Testes~Uterus~Stomach~Make a clinical structure-and-function table using no personal information.
Gametes and inherited information~gamete~a reproductive cell such as an egg or sperm~Egg and sperm cells carry inherited information. In humans, each normally has half the chromosome number of ordinary body cells. Joining them restores the usual number in the fertilised cell.~How does a human gamete’s chromosome number compare with a typical body cell?~It is half~It is double~It is always zero~Draw two gamete symbols joining, with chromosome sets shown schematically.
The menstrual cycle~ovulation~release of an egg from an ovary~The menstrual cycle involves hormonal changes, possible ovulation and changes in the uterus lining. If pregnancy does not occur, the lining can be shed as a period. Cycle length varies, rather than always being exactly 28 days.~Does every menstrual cycle last exactly 28 days?~No~Yes~Only during school term~Draw a general cycle with no fixed timetable for an individual.
Fertilisation and implantation~implantation~attachment of an early embryo to the uterus lining~Fertilisation joins egg and sperm, usually in an oviduct. Cell division follows; an early embryo may implant in the uterus lining. Fertilisation and implantation are distinct stages.~Is implantation the same event as fertilisation?~No~Yes~Only if the embryo is small~Draw fertilisation, early cell division and implantation as separate stages.
Placenta and exchange~placenta~an organ supporting exchange during pregnancy~The placenta supports exchange of oxygen, nutrients and waste between pregnant person and developing fetus. The two blood supplies normally do not mix directly. Exchange across a surface is not simply one shared blood tube.~Do the two blood supplies normally mix directly in the placenta?~No~Yes~Only every morning~Draw a simplified exchange surface with distinct blood-route labels.
Gestation and birth~gestation~the period of development before birth~A fetus develops during pregnancy and is later born. Duration and development vary. Biological descriptions do not replace clinical advice, and private concerns should be taken to a trusted grown-up or qualified professional.~What is gestation?~Development before birth~The same as digestion~Only the moment of fertilisation~Make a respectful development-stage glossary without personal details.
`,'https://www.nhs.uk/pregnancy/');
unit(9,'Genes, variation and selection','Inherited information influences characteristics alongside environmental conditions. Population change needs several generations. Avoid simplistic claims about people from a single feature; use fictional organisms in diagrams.',
 ['How should a claimed genetic cause be evaluated?','Consider inherited and environmental evidence','Assume resemblance proves one simple gene rule','Ignore all environmental conditions','Many characteristics involve several genes and environmental influences. One resemblance alone does not identify the mechanism.'],`
DNA and genes~gene~a section of DNA involved in a biological function~Genes are sections of DNA. DNA is organised into chromosomes in typical plant and animal nuclei. A gene is not a tiny finished characteristic such as a miniature eye.~What is a gene?~A section of DNA~A whole tiny organ~A blood vessel~Draw DNA, chromosome and nucleus relationships with a not-to-scale label.
Chromosomes and inheritance~chromosome~an organised structure containing DNA~Offspring inherit genetic information from parents. In human sexual reproduction, egg and sperm contribute chromosome sets. Most visible characteristics cannot be explained by looking at one diagram of a chromosome.~What do chromosomes contain?~DNA~Only water~Only fat~Make a schematic chromosome-inheritance diagram using fictional examples.
Inherited and acquired differences~acquired~developing through environment or experience rather than inherited directly~A scar arises through experience rather than being inherited as the same scar. Plant growth can reflect water conditions. Some traits involve both inherited and environmental effects.~Which is an acquired difference?~A scar from an injury~An inherited DNA variant~A gamete’s chromosome set~Sort fictional examples into inherited, acquired or mixed influence.
Mutation and variation~mutation~a change in genetic material~Mutations can create genetic variation. Their effects can be harmful, helpful or have little effect depending on context. They are not always changes organisms wanted or needed.~Are all mutations helpful?~No~Yes~Only if they occur in plants~Draw a fictional DNA-change model with several possible outcomes labelled.
Selection over generations~selection pressure~a condition affecting relative survival or reproduction~An environmental condition can affect which inherited variants leave more offspring. Populations can change across generations. Individuals do not deliberately rewrite genes to meet a need.~What changes through natural selection over generations?~Variant frequencies in populations~Every individual’s wishes instantly~All species into one best species~Draw a fictional three-generation population model and state its assumptions.
Selective breeding~selective breeding~choosing parents with desired characteristics~People can select plants or animals with desired traits for breeding. This differs from natural selection, though both involve inheritance. Selection can have drawbacks, including reduced genetic diversity.~What distinguishes selective breeding?~People choose parents for desired traits~No inheritance is involved~Every offspring is guaranteed identical~Make a plant-breeding goal card including a possible limitation.
`);
unit(9,'Earth materials and resources','Earth systems move matter over different timescales. Natural cycles do not make every resource rapidly renewable. Use maps, diagrams and published data; no mining, rock breaking, burning or household chemical testing is needed.',
 ['How should a resource claim be checked?','Compare replenishment timescales and extraction effects','Assume natural means unlimited','Ignore the system boundary','A resource can be naturally formed yet finite on human timescales. Environmental costs need evidence.'],`
The rock cycle has branches~rock cycle~connections between rock-forming and rock-changing processes~Weathering, deposition, burial, heat, pressure and melting connect rock types. There is no one compulsory route for every rock. Metamorphism does not require complete melting.~Must every rock follow one fixed cycle route?~No~Yes~Only if it contains crystals~Draw a branching rock-cycle model with named processes.
Tectonic plates~tectonic plate~a moving section of Earth’s outer rigid layer~Plates include crust and uppermost mantle. They move slowly over geological time. The mantle is mostly solid but can flow slowly; it is not one global ocean of liquid magma.~Is the mantle simply a global liquid magma ocean?~No~Yes~Only beneath oceans~Draw crust, mantle and plates as a labelled not-to-scale model.
Carbon moves through systems~carbon cycle~movement of carbon among organisms, air, water and rocks~Photosynthesis, respiration, decomposition and combustion move carbon. Carbon atoms can enter different substances. Matter cycling is different from useful energy being endlessly recycled.~Which process takes carbon dioxide into organic material?~Photosynthesis~Only combustion~Only boiling water~Draw a carbon-cycle map with stores and process arrows.
Fossil fuels and timescales~finite~limited in amount on the relevant timescale~Coal, oil and gas formed over geological timescales. We use them much faster than they are replenished. Natural origin does not make a resource renewable on useful human timescales.~Why are fossil fuels considered non-renewable?~Replenishment is much slower than use~They are not made of matter~They exist only in laboratory bottles~Compare human-use and formation timescales on a paper timeline.
Greenhouse gases and radiation~greenhouse effect~warming associated with absorption and emission of infrared radiation~Greenhouse gases absorb and emit infrared radiation. Increasing carbon dioxide affects Earth’s energy balance. The mechanism is not the same as the ozone hole or a literal glass roof.~What radiation is important in the greenhouse effect?~Infrared~Only visible green light~Only sound~Draw an illustrative Earth energy-flow model with infrared arrows.
Recycling and resource choices~recycling~processing used material for further use~Recycling can reduce demand for newly extracted material. It still uses energy and may involve losses. Compare whole processes rather than calling any option impact-free.~Does recycling always have zero energy cost?~No~Yes~Only for metal~Make a material-use comparison with extraction, transport and processing stages.
`,'https://www.bgs.ac.uk/discovering-geology/');
unit(9,'Periodic patterns and reaction choices','Element groups share patterns, but observations need specific conditions. Reactions depend on substances and quantities. These lessons are paper chemistry only: no reactive metals, acids, flames, extraction or gases at home.',
 ['How should a reactivity-series prediction be made?','Use the relative positions and state the substances','Assume the most colourful metal wins','Ignore whether a reaction is chemically possible','A series supports specified comparisons. Conditions and actual evidence still matter.'],`
Group 1 patterns~group~a column of the periodic table~Group 1 alkali metals share chemical patterns, including reactions with water. Reactivity generally increases down the group. They are hazardous and are not materials for home investigation.~How does Group 1 reactivity generally change down the group?~It increases~It always decreases~It becomes zero~Annotate a paper Group 1 column with the trend and a no-home-testing note.
Group 7 halogens~halogen~an element in Group 7 in the school convention~Halogens share reaction patterns. Reactivity generally decreases down the school Group 7 column. Colour and state vary, but colour alone is not a reactivity measurement.~How does halogen reactivity generally change down the group?~It decreases~It always increases~It is identical for all~Compare Group 1 and halogen trend arrows on paper.
Noble gases~noble gas~an element in the outermost school Group 0 or modern Group 18~Noble gases have very low reactivity under ordinary conditions. This is linked to stable outer electron arrangements in a simple model. Very unreactive is more careful than never reacting under any conditions.~How are noble gases best described here?~Very unreactive under ordinary conditions~The most reactive gases always~Metals that rust immediately~Make a group-pattern card with the model’s limitation stated.
Metals and dilute acids~salt~an ionic compound formed in many neutralisation reactions~Many sufficiently reactive metals react with suitable dilute acids to form a salt and hydrogen. Not every metal does so. Copper does not behave like magnesium with dilute hydrochloric acid.~Which gas can suitable metal–acid reactions produce?~Hydrogen~Helium~Nitrogen always~Write a generic metal + suitable acid → salt + hydrogen paper equation.
Displacement reactions~displacement~a more reactive element replacing another in a compound~A more reactive metal can displace a less reactive one from a suitable compound. Relative reactivity matters, not metal size. In our imaginary model order A > B > C, most to least reactive, A can displace C from a suitable C compound; C cannot displace A from an A compound. A real reaction needs named substances and suitable conditions.~Which metal can displace a less reactive metal in suitable conditions?~The more reactive metal~Always the physically bigger piece~Always the shinier metal~Use this imaginary model order, most to least reactive: A > B > C. Predict whether metal A would displace C from a suitable C compound and whether metal C would displace A from an A compound. Draw both predictions and explain them using the order; this is a paper model only.
Catalysts and reaction rates~catalyst~a substance speeding a reaction without overall consumption~A catalyst can speed a reaction without being consumed overall. It does not supply unlimited energy or change every reaction into the same products. Different reactions can need different catalysts.~Is a catalyst consumed overall in the reaction it catalyses?~No~Yes~Only if it is drawn small~Draw uncatalysed and catalysed process timelines with equal final amounts.
`);
unit(9,'Thermal transfers and efficiency','Temperature and energy are different quantities. Energy can transfer through conduction, convection and radiation. Use paper models and example data; no hot water, flames, ovens or electrical heating are required.',
 ['What must an insulation comparison record?','Starting conditions, time and temperature measurements','Only blanket colour','Only the final number without units','Starting conditions and elapsed time are needed to interpret temperature changes fairly.'],`
Temperature is not total energy~temperature~a measure associated with average particle kinetic energy~A small hot cup and a large cooler bath can have different thermal energy stores. Temperature alone does not state total stored energy. Amount of matter and material also matter.~Does temperature alone determine total thermal energy stored?~No~Yes~Only for water~Compare two fictional water quantities with different temperatures on paper.
Conduction through materials~conduction~energy transfer through interactions within a material~Energy can transfer from a warmer region to a cooler one through particle interactions. Metals also have mobile electrons contributing to conduction. Material itself need not flow from hot to cold.~Does conduction require the whole solid to flow?~No~Yes~Only if the solid is a metal~Draw a conduction model with energy direction but no bulk material flow.
Convection in fluids~convection~energy transfer involving bulk movement of a fluid~Warm fluid can become less dense and rise under gravity; cooler fluid can sink. Convection needs fluid movement. It is not the same process as conduction through a still solid.~Where can convection occur?~In liquids and gases~Only in rigid solids~Only in empty space~Draw a fluid-circulation model with warming and cooling regions.
Infrared radiation~radiation~energy transfer by electromagnetic waves~Thermal radiation can transfer energy through empty space. It does not need air as sound does. Surfaces emit and absorb radiation in ways that depend on their properties.~Can radiation transfer energy through empty space?~Yes~No~Only if sound accompanies it~Draw energy travelling from Sun to Earth with not-to-scale label.
Insulation slows transfers~insulation~material or design reducing unwanted transfer~Insulation slows energy transfer; it does not create heat. Trapped air can reduce conduction and convection in some designs. Different transfer pathways may need different solutions.~Does insulation create energy by itself?~No~Yes~Only if it is thick~Design a paper insulated container and identify the transfer pathway reduced.
Efficiency calculations~efficiency~useful output divided by total input~If 20 J of a 50 J input is useful output, efficiency is 0.4 or 40%. The rest is transferred in other ways, not destroyed. Define useful for the device’s intended job.~What is 20 J useful from 50 J input as a percentage?~40%~250%~30%~Draw an energy account and calculate the example efficiency.
`);
unit(9,'Space, scale and physical models','Space models connect gravity, motion and measurements. Planets are not equally spaced, and page drawings are not to scale unless specified. Observation methods have limits. Never look directly at the Sun or use optical devices to view it.',
 ['How should a planet-size comparison be interpreted?','Read the scale and separate size from orbital distance','Assume all page gaps are true distances','Assume every planet is the same density','A size model may use a different scale from a distance model. Labels explain what a comparison actually shows.'],`
Gravity keeps orbits curved~gravitational field~a way to describe gravitational effects around a mass~Gravity can change the direction of an orbiting object’s motion. An orbit is not evidence that gravity is absent. A circular sketch is an approximation to many real paths.~Is gravity absent for an orbiting satellite?~No~Yes~Only on the far side of Earth~Draw a satellite with motion direction and inward gravity arrows.
Weight on another world~gravitational field strength~force per unit mass in a gravitational field~Weight equals mass times gravitational field strength. A 2 kg mass in a 5 N/kg field weighs 10 N. The mass remains 2 kg even though weight changes between worlds.~What is 2 kg multiplied by 5 N/kg?~10 N~2.5 N~7 N~Compare fictional world weights for one unchanged mass.
Planets and dwarf planets~dwarf planet~a solar-system body meeting some but not all planet criteria~The solar system has eight recognised planets. Pluto is a dwarf planet. Classification uses orbital and physical criteria, not a claim that Pluto has disappeared or is not a real world.~Is Pluto no longer a real solar-system body?~No; it is a dwarf planet~Yes; it vanished~Yes; it became a star~Make a solar-system classification card with eight planets and Pluto’s category.
Seasons across hemispheres~hemisphere~half of a sphere~Earth’s tilt produces differing seasonal sunlight in its hemispheres during the orbit. When England has summer, the southern hemisphere has winter. This is not mainly a distance-from-Sun effect.~When England has summer, which season is in the southern hemisphere?~Winter~Summer everywhere~No season~Draw opposite seasonal sunlight on a tilted Earth, labelled not to scale.
Light-years measure distance~light-year~the distance light travels in a year~A light-year is a distance unit, not a time interval. Starlight takes time to arrive, so distant stars are seen as they were earlier. Distance and brightness are different quantities.~What does a light-year measure?~Distance~Time only~Mass~Make a distance-versus-time units card using light-year and year.
Stars, galaxies and evidence~galaxy~a large system of stars, gas, dust and other matter~The Sun is one star in the Milky Way galaxy. The solar system is not the whole galaxy. Telescopes provide evidence, while illustrations combine information and often use false colours or altered scales.~Is the solar system the whole Milky Way?~No~Yes~Only at night~Draw nested Earth, solar-system and galaxy boxes labelled not to scale.
`,SPACE_SOURCE);

function question(prompt:string,right:string,wrong:[string,string],hint:string,explanation:string,seed:number):CourseQuestion{
  const answer=seed%3;
  const options=[...wrong];options.splice(answer,0,right);
  return {prompt,options,answer,hint,explanation};
}
function factQuestion(c:Concept,seed:number):CourseQuestion{
  return question(c.prompt,c.right,c.wrong,`Think about ${c.word}: ${c.meaning}.`,`${c.right}. ${c.explanation}`,seed);
}
type ApplicationCheck = [prompt:string,right:string,wrong1:string,wrong2:string,hint:string,explanation:string];
// Targeted application replaces a generic vocabulary/method check. Each card
// still has five questions and keeps the same answer-position rotation.
const APPLICATION_CHECKS:Record<string,{method?:ApplicationCheck;application:ApplicationCheck}>={
  'Roots below the ground':{application:['Which named plant has a yellow flower head and a main taproot?','A dandelion','Common holly','Common oak','Think about our named dandelion picture and its root.','A dandelion has a yellow flower head and a main taproot. A named picture helps us connect the plant name to its parts; we do not need to dig up a plant.']},
  'Flowers and petals':{application:['Which of our plants usually has white outer petals around a yellow middle?','A common daisy','Common oak','Common holly','Compare the named flower pictures and their features.','A common daisy usually has white outer petals around a yellow middle. A dandelion has a yellow flower head. Many plants share colours, so a grown-up can help check names using more than one feature.']},
  'Deciduous trees':{application:['Which named tree is deciduous?','Common oak','Common holly','Every tree with green summer leaves','Think about the tree that loses leaves in autumn.','Common oak is deciduous: it loses leaves in autumn and grows new ones in spring. Common holly keeps leaves through the year. Green leaves in summer alone cannot tell us which group a tree belongs to.']},
  'Evergreen trees':{application:['Which named tree keeps leaves through the year, while still shedding old leaves?','Common holly','Common oak','Every bare tree in winter','Use the meaning of evergreen and our named examples.','Common holly is evergreen. It keeps leaves through the year while replacing old ones. Common oak is deciduous. Evergreen does not mean that every individual leaf stays forever.']},
  'Animal-cell structures':{application:['Which cell structures carry out many stages of aerobic respiration?','Mitochondria','Cell walls','Chloroplasts only','Aerobic respiration uses oxygen and transfers energy for cell activities.','Mitochondria carry out many stages of aerobic respiration in typical plant and animal cells. Energy from food is transferred for cell activities, rather than being created from nothing.']},
  'Plant-cell structures':{application:['What helps a typical mature plant cell stay firm when its vacuole is filled?','Cell sap presses the contents against the cell wall','The vacuole turns into a nucleus','Every root cell starts photosynthesis','Connect the watery sap, the vacuole and the supporting wall.','Water in the vacuole helps press the cell contents against the wall, keeping the cell firm. This support is called turgor. The vacuole does not replace the nucleus or give every root cell chloroplasts.']},
  'Density calculations':{application:['An object floats freely at rest with only weight and upthrust acting vertically. How do those forces compare?','Upthrust balances weight','Upthrust is zero','Weight must be greater than upthrust','At rest, the upward and downward forces have zero resultant.','Upthrust balances weight for this freely floating object at rest. Greater water pressure beneath the object than above it produces an upward force. Balanced forces do not mean that either force is absent.']},
  'Gas pressure and collisions':{
    method:['In the same still water tank, which point has greater liquid pressure?','The point 8 cm below the surface','The point 2 cm below the surface','Both must have zero pressure','Compare depths in the same liquid, not the shape of the tank.','The point 8 cm below the surface has greater pressure than the point 2 cm below it. Liquid pressure increases with depth in the same still liquid because the weight of liquid above the point increases.'],
    application:['Why does atmospheric pressure generally decrease as you climb higher?','There is less weight of air above you','Higher air has no particles','Your height changes the colour of air','Pressure comes from surrounding air; compare the air column above each height.','Atmospheric pressure generally decreases with height because there is less weight of air above you. There are still air particles at ordinary mountain heights; lower pressure does not mean that air has disappeared.']},
  'Elements and proton number':{application:['Which symbol represents carbon?','C','O','H','Use the element-symbol key, rather than the drawing colour.','C represents carbon, O represents oxygen and H represents hydrogen. These symbols identify elements. Carbon atoms have six protons; a symbol is not a literal picture of an atom.']},
  'Molecules and compounds':{
    method:['How many atoms are in one water molecule, H2O?','Two hydrogen atoms and one oxygen atom','One hydrogen atom and two oxygen atoms','Two separate hydrogen molecules and no oxygen','A formula number applies to the element immediately before it; no number means one.','H2O represents two hydrogen atoms and one oxygen atom in each water molecule. The 2 applies to H, and the O has no number so counts as one. The formula describes one molecule, not a mixture of separate elements.'],
    application:['What does 2H2O represent in total?','Four hydrogen atoms and two oxygen atoms in two water molecules','Two hydrogen atoms and four oxygen atoms in one molecule','Four hydrogen atoms and one oxygen atom in two molecules','The front 2 multiplies the whole H2O molecule; count each atom type twice.','2H2O represents two water molecules. Each has two hydrogen atoms and one oxygen atom, giving four hydrogen atoms and two oxygen atoms altogether. A front number changes how many molecules we count, not the formula of each molecule.']},
  'Current and charge conservation':{
    method:['Two objects start neutral. A gains three electrons from B. What are their final charges?','A is negative and B is positive by equal amounts','Both become positive by equal amounts','A is negative and B stays neutral','Electrons have negative charge; count the same transferred electrons for both objects.','A gains three negatively charged electrons and becomes negative. B loses those same three electrons and becomes positive by an equal amount. Their total charge stays unchanged; the model transfers electrons rather than creating charge.'],
    application:['How do a positively charged object and a negatively charged object interact?','They attract through a non-contact electric force','They repel because all charged objects repel','They can exert a force only after touching','Unlike charges attract; an electric field can exert a force without contact.','Unlike charges attract, while like charges repel. An electric field is a region where a charge experiences an electric force. A static charge imbalance and a sustained current in a complete circuit are different situations.']},
};
function applicationQuestion(check:ApplicationCheck,seed:number):CourseQuestion{
  const [prompt,right,wrong1,wrong2,hint,explanation]=check;
  return question(prompt,right,[wrong1,wrong2],hint,explanation,seed);
}
export const SCIENCE_YEAR_PLANS:Record<number,string[]> = {};
export const SCIENCE_LESSONS:CourseLesson[] = UNITS.flatMap((u)=>{
  SCIENCE_YEAR_PLANS[u.year] ??= [];
  const firstWeek=SCIENCE_YEAR_PLANS[u.year].length+1;
  return u.concepts.map((c,index)=>{
    const week=firstWeek+index;
    SCIENCE_YEAR_PLANS[u.year].push(c.title);
    // Earlier/later cards are explicitly retrieval previews, not claims that
    // a learner has already studied them. Together they provide three
    // substantive, related explanations in each weekly session.
    const neighbour=u.concepts[(index+1)%6], other=u.concepts[(index+5)%6];
    const seed=(u.year-1)*36+week-1;
    const checks=APPLICATION_CHECKS[c.title];
    const [enquiryPrompt,enquiryRight,enquiryWrong1,enquiryWrong2,enquiryExplanation]=u.enquiry;
    const young=u.year<=2;
    const practice=young
      ? `Our word is “${c.word}”. It means ${c.meaning}. Look at a picture, draw or tell a grown-up your idea. ${c.task} Say which part of your picture helps answer our question.`
      : `Use “${c.word}” accurately: ${c.meaning}. ${c.task} Label the important features and explain their roles. State what the model or observation shows and one question it cannot answer on its own.`;
    const explanation=young
      ? `Our answer is ${c.right}. ${c.explanation} We can explain it using this clue: ${c.meaning}. Draw or tell a grown-up the reason, rather than just choosing a word.`
      : `Answer: ${c.right}. ${c.explanation} Connect the named feature or quantity to its scientific meaning: ${c.meaning}. A labelled model helps communicate this explanation, but it is not a new measurement or proof of every related claim.`;
    return {
      id:`science-y${u.year}-w${String(week).padStart(2,'0')}-s1`,subject:'science',year:u.year,week,session:1,
      title:c.title,unit:u.name,
      objective:young ? `Find out about ${c.title.toLowerCase()}. Use our word “${c.word}”, then draw or tell how it works.` : `Explain ${c.title.toLowerCase()} using the meaning of ${c.word}, and communicate the reasoning with a labelled model or record.`,
      teaching:[`${u.introduction} ${c.explanation}`,`${young?'Two connected ideas':'Connect and revisit'}: ${other.explanation} ${neighbour.explanation}`,`${enquiryPrompt} ${enquiryExplanation}`,practice],
      vocabulary:[{word:c.word,meaning:c.meaning},{word:neighbour.word,meaning:neighbour.meaning},{word:young?'observe':'model',meaning:young?'look closely and notice details':'a simplified representation used to explain selected features'}],
      example:{prompt:c.prompt,explanation},
      questions:[factQuestion(c,seed),factQuestion(neighbour,seed+1),factQuestion(other,seed+2),
        checks?.method ? applicationQuestion(checks.method,seed+3) : question(enquiryPrompt,enquiryRight,[enquiryWrong1,enquiryWrong2],'Choose the method or interpretation linked to our evidence.',enquiryExplanation,seed+3),
        checks ? applicationQuestion(checks.application,seed+4) : question(`In ${c.title.toLowerCase()}, what does “${c.word}” mean?`,c.meaning,[neighbour.meaning,other.meaning],`Use the vocabulary and the explanation about ${c.word}.`,`${c.word} means ${c.meaning}. ${c.explanation}`,seed+4)],
      mission:{title:young?`${c.title}: draw and discover`:`${c.title}: evidence notebook`,instructions:[
        `2 minutes: ${c.task} Use paper, a picture or a safe familiar observation with a grown-up.`,
        `3 minutes: ${young?'Add labels and tell a grown-up':'Add precise labels and a short explanation of'} what the picture or record shows. Use “${c.word}”. Mark imagined numbers as example data and drawings as models, not to scale where relevant.`,
        `2 minutes: ${young?'Tell one thing you found out and ask another question':'Review the explanation, identify a limitation and write a next question'}. No heating, chemicals, electrical assembly, animal handling or tasting is needed.`]},
      reflection:young?`Draw or tell what you learned about ${c.word}. What clue helped? What else would you like to find out?`:`Explain ${c.word} in this lesson’s context. What supports the explanation, what does your model leave out, and what could a teacher-supervised investigation check?`,
      source:u.source,
    };
  });
});

